void check(const std::string& test, double got, double limit)
{
    if (!(got <= limit)) {
        std::printf("FAIL %-52s got %.6e, limit %.6e\n", test.c_str(), got, limit);
        ++failures;
    }
}

struct Diff {
    double abs = 0, rel = 0, ulp = 0;
    void add(double a, double b)
    {
        const double d = std::abs(a - b);
        const double scale = std::max({std::abs(a), std::abs(b), 1.0});
        abs = std::max(abs, d);
        if (std::abs(b) > 1.0e-14) rel = std::max(rel, d / std::abs(b));
        ulp = std::max(ulp, d / (std::numeric_limits<double>::epsilon() * scale));
    }
    void merge(const Diff& o)
    {
        abs = std::max(abs, o.abs); rel = std::max(rel, o.rel); ulp = std::max(ulp, o.ulp);
    }
};

std::string data_path(const char* name)
{
    const std::string source = __FILE__;
    const std::string marker = "/tests/unit/nonmatching_3d.cpp";
    const std::string::size_type position = source.rfind(marker);
    return source.substr(0, position) + "/backend/Preprocessing/" + name;
}

// Exact lattice value of a master coordinate: master nodes of order p lie on
// multiples of 1/p for the orders used here; any other value is kept.
double lattice(double v, int p)
{
    const double r = std::round(v * p) / p;
    return std::abs(v - r) < 1.0e-13 ? r : v;
}

// Monomial exponent sets: total degree (simplex) or tensor (quad/hex).
std::vector<std::vector<int>> exponents(int dim, int p, bool simplex)
{
    std::vector<std::vector<int>> e;
    std::vector<int> a(dim, 0);
    std::function<void(int)> rec = [&](int k) {
        if (k == dim) {
            int s = 0;
            for (int v : a) s += v;
            if (!simplex || s <= p) e.push_back(a);
            return;
        }
        for (int v = 0; v <= p; ++v) { a[k] = v; rec(k + 1); }
    };
    rec(0);
    return e;
}

// Long-double nodal Lagrange basis on the given nodes (column-major [n, dim]).
// value[k + n*j] and grad[(k + n*j) + n*m*d] at points (column-major [m, dim]).
void reference_basis(std::vector<long double>& value, std::vector<long double>& grad,
                     const std::vector<long double>& nodes, int n,
                     const std::vector<long double>& pts, int m, int dim, int p, bool simplex)
{
    const auto E = exponents(dim, p, simplex);
    if (static_cast<int>(E.size()) != n) {
        std::printf("FAIL reference basis size %zu != %d\n", E.size(), n);
        ++failures;
        return;
    }
    auto mono = [&](const long double* x, int stride, const std::vector<int>& e, int dd) {
        long double v = 1;
        for (int d = 0; d < dim; ++d) {
            int k = e[d];
            long double c = 1;
            if (d == dd) { if (k == 0) return (long double)0; c = k; k -= 1; }
            long double xp = 1;
            for (int i = 0; i < k; ++i) xp *= x[d * stride];
            v *= c * xp;
        }
        return v;
    };
    // Solve V^T C = I with V[i][e] = mono(node_i, e): C[e][k] are coefficients of phi_k.
    std::vector<long double> A(n * n), C(n * n, 0);
    for (int i = 0; i < n; ++i)
        for (int a = 0; a < n; ++a) A[i + n * a] = mono(&nodes[i], n, E[a], -1);
    for (int k = 0; k < n; ++k) C[k + n * k] = 1;   // right-hand sides: rows = nodes
    // Gaussian elimination with partial pivoting on A (rows i), applied to C rows.
    std::vector<int> piv(n);
    for (int c = 0; c < n; ++c) {
        int best = c;
        for (int r = c + 1; r < n; ++r)
            if (std::fabs(A[r + n * c]) > std::fabs(A[best + n * c])) best = r;
        if (best != c) {
            for (int a = 0; a < n; ++a) std::swap(A[c + n * a], A[best + n * a]);
            for (int a = 0; a < n; ++a) std::swap(C[c + n * a], C[best + n * a]);
        }
        for (int r = c + 1; r < n; ++r) {
            const long double f = A[r + n * c] / A[c + n * c];
            for (int a = c; a < n; ++a) A[r + n * a] -= f * A[c + n * a];
            for (int a = 0; a < n; ++a) C[r + n * a] -= f * C[c + n * a];
        }
    }
    // X solves A X = C (A: [node, exponent]); X[e][k] = coefficient of exponent e in phi_k.
    std::vector<long double> X(n * n, 0);
    for (int k = 0; k < n; ++k)
        for (int r = n - 1; r >= 0; --r) {
            long double s = C[r + n * k];
            for (int a = r + 1; a < n; ++a) s -= A[r + n * a] * X[a + n * k];
            X[r + n * k] = s / A[r + n * r];
        }
    value.assign(static_cast<std::size_t>(n) * m, 0);
    grad.assign(static_cast<std::size_t>(n) * m * dim, 0);
    for (int j = 0; j < m; ++j)
        for (int a = 0; a < n; ++a) {
            const long double mv = mono(&pts[j], m, E[a], -1);
            for (int k = 0; k < n; ++k) value[k + n * j] += mv * X[a + n * k];
            for (int d = 0; d < dim; ++d) {
                const long double dm = mono(&pts[j], m, E[a], d);
                for (int k = 0; k < n; ++k)
                    grad[(k + n * j) + static_cast<std::size_t>(n) * m * d] += dm * X[a + n * k];
            }
        }
}

void transform_face_point(int elemtype,int orientation,const dstype in[2],dstype out[2])
{
    if(elemtype==0) {
        const dstype lambda[3]={1-in[0]-in[1],in[0],in[1]};
        static const int permutation[6][3]={{0,1,2},{1,2,0},{2,0,1},
            {0,2,1},{2,1,0},{1,0,2}};
        const dstype mapped[3]={lambda[permutation[orientation][0]],
            lambda[permutation[orientation][1]],lambda[permutation[orientation][2]]};
        out[0]=mapped[1]; out[1]=mapped[2];
    }
    else {
        const dstype u=in[0],v=in[1];
        switch(orientation) {
        case 0: out[0]=u; out[1]=v; break;
        case 1: out[0]=1-v; out[1]=u; break;
        case 2: out[0]=1-u; out[1]=1-v; break;
        case 3: out[0]=v; out[1]=1-u; break;
        case 4: out[0]=1-u; out[1]=v; break;
        case 5: out[0]=u; out[1]=1-v; break;
        case 6: out[0]=v; out[1]=u; break;
        default: out[0]=1-v; out[1]=1-u; break;
        }
    }
}

struct StageReport {
    Diff topology, geometry, basisMaster, basisTypeOne, basisMasterVsTypeOne, volumeGauss, volumeNodalGrad,
         traceMaster, traceTypeOne, integralMaster, integralTypeOne;
};

void print_diff(const char* label, const Diff& d)
{
    std::printf("    %-34s abs %.3e  rel %.3e  ulp %.3e\n", label, d.abs, d.rel, d.ulp);
}

StageReport family_case(int elemtype, int p)
{
    StageReport r;
    const int nd = 3, ndf = 2;
    const bool simplex = elemtype == 0;
    std::vector<double> xpe, xpf;
    std::vector<int> telem, tface, perm;
    masternodes(xpe, telem, xpf, tface, perm, p, nd, elemtype, data_path("masternodes.bin"));
    const int npe = static_cast<int>(xpe.size()) / nd;
    const int npf = static_cast<int>(xpf.size()) / ndf;
    const int nfe = static_cast<int>(perm.size()) / npf;
    std::vector<double> gpf, gwf;
    gaussnodes(gpf, gwf, 2 * p, ndf, elemtype, data_path("gaussnodes.bin"));
    const int ngf = static_cast<int>(gwf.size());

    // Exact lattice coordinates (stage 2 reference).
    std::vector<long double> xpeExact(xpe.size()), xpfExact(xpf.size()), gpfL(gpf.begin(), gpf.end());
    for (std::size_t i = 0; i < xpe.size(); ++i) {
        xpeExact[i] = lattice(xpe[i], p);
        r.geometry.add(xpe[i], static_cast<double>(xpeExact[i]));
    }
    for (std::size_t i = 0; i < xpf.size(); ++i) {
        xpfExact[i] = lattice(xpf[i], p);
        r.geometry.add(xpf[i], static_cast<double>(xpfExact[i]));
    }

    // Stage 1: every face node of face f is a distinct element node lying on
    // the face plane; distances are measured with the stored coordinates.
    for (int f = 0; f < nfe; ++f) {
        std::vector<int> seen;
        long double a[3], b[3], c[3];
        auto node = [&](int j, long double* x) {
            for (int d = 0; d < nd; ++d) x[d] = xpe[perm[j + npf * f] + npe * d];
        };
        // Plane through face nodes 0 and 1 and the face node farthest from their line.
        node(0, a); node(1, b);
        long double u[3], v[3], nrm[3] = {0, 0, 0}, nn = 0;
        for (int d = 0; d < 3; ++d) u[d] = b[d] - a[d];
        for (int j = 2; j < npf; ++j) {
            node(j, c);
            long double w[3];
            for (int d = 0; d < 3; ++d) v[d] = c[d] - a[d];
            w[0] = u[1] * v[2] - u[2] * v[1];
            w[1] = u[2] * v[0] - u[0] * v[2];
            w[2] = u[0] * v[1] - u[1] * v[0];
            const long double wn = std::sqrt(w[0] * w[0] + w[1] * w[1] + w[2] * w[2]);
            if (wn > nn) { nn = wn; for (int d = 0; d < 3; ++d) nrm[d] = w[d]; }
        }
        for (int j = 0; j < npf; ++j) {
            const int e = perm[j + npf * f];
            if (e < 0 || e >= npe || std::find(seen.begin(), seen.end(), e) != seen.end()) {
                std::printf("FAIL topology: bad permutation entry (family %d, p %d, face %d)\n",
                            elemtype, p, f);
                ++failures;
            }
            seen.push_back(e);
            long double x[3];
            node(j, x);
            long double dist = 0;
            for (int d = 0; d < 3; ++d) dist += (x[d] - a[d]) * nrm[d];
            r.topology.add(static_cast<double>(dist / nn), 0.0);
        }
    }

    // Stage 3: face tables at the face Gauss points.
    std::vector<double> shapfg(static_cast<std::size_t>(npf) * ngf * (ndf + 1));
    mkshape(shapfg, xpf, gpf, ngf, elemtype, p, ndf, npf);          // production master table
    std::vector<long double> refValue, refGrad;
    reference_basis(refValue, refGrad, xpfExact, npf, gpfL, ngf, ndf, p, simplex);
    SurfaceNodalBasis typeOne(xpf.data(), npf, p, elemtype);
    std::vector<double> psi(npf), dpsi(npf * ndf), typeOneValue(static_cast<std::size_t>(npf) * ngf);
    for (int g = 0; g < ngf; ++g) {
        const double xi[2] = {gpf[g], gpf[g + ngf]};
        typeOne.evaluate(psi.data(), dpsi.data(), xi);
        for (int k = 0; k < npf; ++k) {
            const double master = shapfg[k + npf * g];
            const double ref = static_cast<double>(refValue[k + npf * g]);
            typeOneValue[k + npf * g] = psi[k];
            r.basisMaster.add(master, ref);
            r.basisTypeOne.add(psi[k], ref);
            r.basisMasterVsTypeOne.add(master, psi[k]);
        }
    }

    // Stage 3b: volume table (values and derivatives) at the volume Gauss points (shapeg).
    {
        std::vector<double> gpe, gwe;
        gaussnodes(gpe, gwe, 2 * p, nd, elemtype, data_path("gaussnodes.bin"));
        const int nge = static_cast<int>(gwe.size());
        std::vector<double> shapeg(static_cast<std::size_t>(npe) * nge * (nd + 1));
        mkshape(shapeg, xpe, gpe, nge, elemtype, p, nd, npe);
        std::vector<long double> v, gr, gpeL(gpe.begin(), gpe.end());
        reference_basis(v, gr, xpeExact, npe, gpeL, nge, nd, p, simplex);
        for (int j = 0; j < nge; ++j)
            for (int k = 0; k < npe; ++k) {
                r.volumeGauss.add(shapeg[k + npe * j], static_cast<double>(v[k + npe * j]));
                for (int d = 0; d < nd; ++d)
                    r.volumeGauss.add(
                        shapeg[k + npe * j + static_cast<std::size_t>(npe) * nge * (d + 1)],
                        static_cast<double>(gr[(k + npe * j) + static_cast<std::size_t>(npe) * nge * d]));
            }
    }

    // Stage 3c: volume derivative table at the master nodes (shapen).
    {
        std::vector<double> shapen(static_cast<std::size_t>(npe) * npe * (nd + 1));
        std::vector<double> xpeCopy(xpe);
        mkshape(shapen, xpeCopy, xpe, npe, elemtype, p, nd, npe);
        std::vector<long double> v, gr, xpeL(xpe.begin(), xpe.end());
        reference_basis(v, gr, xpeExact, npe, xpeL, npe, nd, p, simplex);
        for (int d = 0; d < nd; ++d)
            for (int j = 0; j < npe; ++j)
                for (int k = 0; k < npe; ++k)
                    r.volumeNodalGrad.add(
                        shapen[k + npe * j + static_cast<std::size_t>(npe) * npe * (d + 1)],
                        static_cast<double>(gr[(k + npe * j) + static_cast<std::size_t>(npe) * npe * d]));
    }

    // Stages 4 and 5: a degree-p trace g(xi) = (0.3 + xi0 + 2 xi1)^p + xi0 xi1^(p-1).
    auto g = [&](long double s, long double t) {
        long double base = 1, a = 0.3L + s + 2 * t;
        for (int i = 0; i < p; ++i) base *= a;
        long double extra = s;
        for (int i = 0; i < p - 1; ++i) extra *= t;
        return base + extra;
    };
    std::vector<double> nodal(npf);
    for (int k = 0; k < npf; ++k) nodal[k] = static_cast<double>(g(xpfExact[k], xpfExact[k + npf]));
    for (int gp = 0; gp < ngf; ++gp) {
        long double sm = 0, s1 = 0;
        for (int k = 0; k < npf; ++k) {
            sm += shapfg[k + npf * gp] * static_cast<long double>(nodal[k]);
            s1 += typeOneValue[k + npf * gp] * static_cast<long double>(nodal[k]);
        }
        const double exact = static_cast<double>(g(gpfL[gp], gpfL[gp + ngf]));
        r.traceMaster.add(static_cast<double>(sm), exact);
        r.traceTypeOne.add(static_cast<double>(s1), exact);
    }
    for (int k = 0; k < npf; ++k) {
        long double im = 0, i1 = 0, ie = 0;
        for (int gp = 0; gp < ngf; ++gp) {
            const long double gv = g(gpfL[gp], gpfL[gp + ngf]);
            im += shapfg[k + npf * gp] * gwf[gp] * gv;
            i1 += typeOneValue[k + npf * gp] * gwf[gp] * gv;
            ie += refValue[k + npf * gp] * gwf[gp] * gv;
        }
        r.integralMaster.add(static_cast<double>(im), static_cast<double>(ie));
        r.integralTypeOne.add(static_cast<double>(i1), static_cast<double>(ie));
    }

    const char* name = simplex ? "tet" : "hex";
    std::printf("%s p=%d (npe %d, npf %d, ngf %d)\n", name, p, npe, npf, ngf);
    print_diff("1 topology (face-plane distance)", r.topology);
    print_diff("2 geometry (stored vs lattice)", r.geometry);
    print_diff("3 basis: master table vs ref", r.basisMaster);
    print_diff("3 basis: type-1 basis vs ref", r.basisTypeOne);
    print_diff("3 basis: master vs type-1", r.basisMasterVsTypeOne);
    print_diff("3b volume table at Gauss pts vs ref", r.volumeGauss);
    print_diff("3c volume nodal grad vs ref", r.volumeNodalGrad);
    print_diff("4 trace interp: master vs exact", r.traceMaster);
    print_diff("4 trace interp: type-1 vs exact", r.traceTypeOne);
    print_diff("5 face integral: master vs ref", r.integralMaster);
    print_diff("5 face integral: type-1 vs ref", r.integralTypeOne);

    // First diverging stage of the master-table (type-0) data.
    const char* first = "none";
    if (r.topology.abs > m0Tolerance) first = "1 topology/ordering";
    else if (r.geometry.abs > m0Tolerance) first = "2 geometry";
    else if (r.basisMaster.abs > m0Tolerance) first = "3 basis (master face table)";
    else if (r.volumeGauss.abs > m0Tolerance) first = "3b basis (volume Gauss-point table)";
    else if (r.traceMaster.abs > m0Tolerance) first = "4 trace interpolation";
    else if (r.integralMaster.abs > m0Tolerance) first = "5 face integration";
    std::printf("    first diverging stage: %s\n", first);

    const std::string tag = std::string(name) + " p=" + std::to_string(p);
    check(tag + " topology", r.topology.abs, exactTolerance);
    check(tag + " type-1 surface basis vs reference", r.basisTypeOne.abs, exactTolerance);
    check(tag + " type-1 trace interpolation", r.traceTypeOne.rel, exactTolerance);
    check(tag + " type-1 face integral", r.integralTypeOne.abs, exactTolerance);
    if (!simplex || strict) {
        check(tag + " master face table vs reference", r.basisMaster.abs, simplex ? m0Tolerance : exactTolerance);
        check(tag + " master trace interpolation", r.traceMaster.rel, simplex ? m0Tolerance : exactTolerance);
        check(tag + " master face integral", r.integralMaster.abs, simplex ? m0Tolerance : exactTolerance);
    }
    return r;
}

#ifdef HAVE_MPI
struct SetupMaster3D {
    Int elemtype = 0, porder = 2, npe = 0, npf = 0, nfe = 0, ngf = 0;
    std::vector<dstype> xpe, xpf, gpf, gwf, shapfgt;
    std::vector<Int> perm, ndims;
};

SetupMaster3D setup_master(int elemtype, int porder)
{
    SetupMaster3D m;
    m.elemtype = elemtype;
    m.porder = porder;
    std::vector<int> telem, tface, perm;
    masternodes(m.xpe,telem,m.xpf,tface,perm,porder,3,elemtype,data_path("masternodes.bin"));
    m.perm.assign(perm.begin(),perm.end());
    gaussnodes(m.gpf,m.gwf,2*porder,2,elemtype,data_path("gaussnodes.bin"));
    m.npe=static_cast<Int>(m.xpe.size()/3);
    m.npf=static_cast<Int>(m.xpf.size()/2);
    m.nfe=static_cast<Int>(m.perm.size()/m.npf);
    m.ngf=static_cast<Int>(m.gwf.size());
    m.shapfgt.assign(static_cast<std::size_t>(3)*m.ngf*m.npf,0.0);
    std::vector<dstype> psi(m.npf),dpsi(static_cast<std::size_t>(2)*m.npf);
    for(Int g=0;g<m.ngf;++g) {
        const dstype xi[2]={m.gpf[g],m.gpf[g+m.ngf]};
        exasim::nonmatching::EvaluateFaceShapeAndGradients(psi.data(),dpsi.data(),xi,m.xpf.data(),3,
            m.npf,elemtype,porder);
        for(Int j=0;j<m.npf;++j) {
            m.shapfgt[g+m.ngf*j]=psi[j];
            m.shapfgt[m.ngf*m.npf+g+m.ngf*j]=dpsi[j];
            m.shapfgt[2*m.ngf*m.npf+g+m.ngf*j]=dpsi[j+m.npf];
        }
    }
    m.ndims.assign(20,0);
    m.ndims[0]=3; m.ndims[1]=elemtype; m.ndims[3]=porder;
    m.ndims[4]=2*porder; m.ndims[5]=m.npe; m.ndims[6]=m.npf; m.ndims[8]=m.ngf;
    return m;
}

void orientation_operator_case(int elemtype,int p,int worldRank)
{
    SetupMaster3D m=setup_master(elemtype,p);
    const int count=elemtype==0?6:8;
    SurfaceNodalBasis production(m.xpf.data(),m.npf,p,elemtype);
    std::vector<long double> nodes(m.xpf.begin(),m.xpf.end());
    dstype worstBasis=0,worstMatrix=0,worstProduct=0;
    for(int orientation=0;orientation<count;++orientation) {
        std::vector<dstype> points(static_cast<std::size_t>(2)*m.ngf);
        for(Int g=0;g<m.ngf;++g) {
            const dstype in[2]={m.gpf[g],m.gpf[g+m.ngf]};
            dstype out[2]; transform_face_point(elemtype,orientation,in,out);
            points[g]=out[0]; points[g+m.ngf]=out[1];
        }
        std::vector<long double> pointLong(points.begin(),points.end()),reference,gradient;
        reference_basis(reference,gradient,nodes,m.npf,pointLong,m.ngf,2,p,elemtype==0);
        std::vector<dstype> H(static_cast<std::size_t>(m.npf)*m.npf,0.0);
        std::vector<long double> Href(static_cast<std::size_t>(m.npf)*m.npf,0.0L);
        std::vector<dstype> psi(m.npf),dpsi(static_cast<std::size_t>(2)*m.npf);
        for(Int g=0;g<m.ngf;++g) {
            const dstype xi[2]={points[g],points[g+m.ngf]};
            production.evaluate(psi.data(),dpsi.data(),xi);
            for(Int j=0;j<m.npf;++j) {
                worstBasis=std::max(worstBasis,std::abs(psi[j]-dstype(reference[j+m.npf*g])));
                for(Int i=0;i<m.npf;++i) {
                    const dstype owner=m.shapfgt[g+m.ngf*i];
                    H[i+m.npf*j]+=m.gwf[g]*owner*psi[j];
                    Href[i+m.npf*j]+=static_cast<long double>(m.gwf[g])*owner*
                        reference[j+m.npf*g];
                }
            }
        }
        std::vector<dstype> trace(m.npf),product(m.npf,0.0),productRef(m.npf,0.0);
        for(Int j=0;j<m.npf;++j) trace[j]=0.03*(1+j)+0.002*orientation;
        for(Int j=0;j<m.npf;++j) for(Int i=0;i<m.npf;++i) {
            worstMatrix=std::max(worstMatrix,std::abs(H[i+m.npf*j]-dstype(Href[i+m.npf*j])));
            product[i]+=H[i+m.npf*j]*trace[j];
            productRef[i]+=dstype(Href[i+m.npf*j])*trace[j];
        }
        for(Int i=0;i<m.npf;++i)
            worstProduct=std::max(worstProduct,std::abs(product[i]-productRef[i]));
    }
    if(worstBasis>5e-13 || worstMatrix>5e-13 || worstProduct>=1e-13) {
        std::printf("FAIL 3D orientation operators family %d rank %d basis %.3e matrix %.3e product %.3e\n",
            elemtype,worldRank,worstBasis,worstMatrix,worstProduct); ++failures;
    }
    if(worldRank==0)
        std::printf("3D orientation operators family %d orientations %d: basis %.3e matrix %.3e product %.3e\n",
            elemtype,count,worstBasis,worstMatrix,worstProduct);
}

struct SetupRank3D {
    std::vector<Int> problem,nsize,appdims,meshdims,bf,elempart,intfaces,interfacefluxmap,elemcon,f2e;
    std::vector<dstype> xdg,udg,uh,wdg,wsrc;
    appstruct app;
    masterstruct master;
    meshstruct mesh;
    solstruct sol;
};

void setup_rank_3d(SetupRank3D& r,SetupMaster3D& m,int model,int part,int modelRanks,
                   dstype gap = 0.0)
{
    r.problem.assign(35,0);
    r.problem[28]=1; r.problem[29]=1; r.problem[30]=2; r.problem[34]=1;
    r.nsize.assign(30,0); r.nsize[2]=35; r.nsize[14]=1;
    r.appdims.assign(30,0);
    r.appdims[AppNdims::nd]=3; r.appdims[AppNdims::nc]=1;
    r.appdims[AppNdims::ncu]=1; r.appdims[AppNdims::ncq]=0;
    r.appdims[AppNdims::ncx]=3;
    r.meshdims.assign(20,0); r.meshdims[0]=3; r.meshdims[1]=1; r.meshdims[4]=m.nfe;
    r.bf.assign(m.nfe,1); r.bf[0]=2;
    r.elempart.assign(1,part);
    r.intfaces.assign(1,0);
    r.interfacefluxmap.assign(1,0);

    const Int i0=m.perm[0], i1=m.perm[1];
    dstype c[3]={m.xpe[i0],m.xpe[i0+m.npe],m.xpe[i0+2*m.npe]};
    dstype t1[3]={m.xpe[i1]-c[0],m.xpe[i1+m.npe]-c[1],m.xpe[i1+2*m.npe]-c[2]};
    dstype n1=std::sqrt(t1[0]*t1[0]+t1[1]*t1[1]+t1[2]*t1[2]);
    for(int d=0;d<3;++d) t1[d]/=n1;
    dstype t2[3]={0,0,0};
    for(Int q=2;q<m.npf;++q) {
        const Int iq=m.perm[q];
        dstype v[3]={m.xpe[iq]-c[0],m.xpe[iq+m.npe]-c[1],m.xpe[iq+2*m.npe]-c[2]};
        const dstype projection=v[0]*t1[0]+v[1]*t1[1]+v[2]*t1[2];
        for(int d=0;d<3;++d) t2[d]=v[d]-projection*t1[d];
        const dstype n2=std::sqrt(t2[0]*t2[0]+t2[1]*t2[1]+t2[2]*t2[2]);
        if(n2>1e-8) { for(int d=0;d<3;++d) t2[d]/=n2; break; }
    }
    dstype normal[3]={t1[1]*t2[2]-t1[2]*t2[1],
        t1[2]*t2[0]-t1[0]*t2[2],t1[0]*t2[1]-t1[1]*t2[0]};
    dstype centroid[3]={0,0,0};
    for(Int j=0;j<m.npe;++j)
        for(int d=0;d<3;++d) centroid[d]+=m.xpe[j+m.npe*d]/m.npe;
    const dstype inward=(centroid[0]-c[0])*normal[0]+(centroid[1]-c[1])*normal[1]+
        (centroid[2]-c[2])*normal[2];
    if(inward<0) for(int d=0;d<3;++d) normal[d]=-normal[d];
    r.xdg.assign(static_cast<std::size_t>(3)*m.npe,0.0);
    const dstype side=model==0?-1.0:1.0;
    for(Int j=0;j<m.npe;++j) {
        const dstype v[3]={m.xpe[j]-c[0],m.xpe[j+m.npe]-c[1],m.xpe[j+2*m.npe]-c[2]};
        const dstype a=v[0]*t1[0]+v[1]*t1[1]+v[2]*t1[2];
        const dstype b=v[0]*t2[0]+v[1]*t2[1]+v[2]*t2[2];
        const dstype h=v[0]*normal[0]+v[1]*normal[1]+v[2]*normal[2];
        r.xdg[j]=0.5+(model==0?-0.5:0.5)*gap+side*h;
        r.xdg[j+m.npe]=3.0*part+a;
        r.xdg[j+2*m.npe]=b;
    }

    r.app=appstruct(); r.master=masterstruct(); r.mesh=meshstruct(); r.sol=solstruct();
    r.app.problem=r.problem.data(); r.app.nsize=r.nsize.data(); r.app.ndims=r.appdims.data();
    r.app.interfacefluxmap=r.interfacefluxmap.data();
    r.master.ndims=m.ndims.data(); r.master.xpe=m.xpe.data(); r.master.xpf=m.xpf.data();
    r.master.gpf=m.gpf.data(); r.master.gwf=m.gwf.data(); r.master.shapfgt=m.shapfgt.data();
    r.mesh.ndims=r.meshdims.data(); r.mesh.bf=r.bf.data(); r.mesh.perm=m.perm.data();
    r.mesh.elempart=r.elempart.data(); r.mesh.szelempart=1;
    r.mesh.intfaces=r.intfaces.data(); r.mesh.szintfaces=1;
    r.sol.xdg=r.xdg.data();
    (void)modelRanks;
}

dstype verify_runtime_matvec(const char* label,SetupRank3D& r,const SetupMaster3D& m,
        commonstruct& common,resstruct& residual,nonmatchingdata& nm,
        exasim::nonmatching::NonmatchingRuntime<dstype,Int>& runtime,
        Int ncu,Int ncu12,int worldRank)
{
    const Int ne=common.meshsizes.ne,ndf=m.npf*m.nfe,mtrace=ndf*ncu;
    const Int nf=m.nfe*ne,N=ncu*m.npf*nf;
    r.f2e.assign(static_cast<std::size_t>(4)*nf,-1);
    for(Int e=0;e<ne;++e) for(Int lf=0;lf<m.nfe;++lf) {
        const Int face=lf+m.nfe*e;
        r.f2e[4*face]=e; r.f2e[4*face+1]=lf;
    }
    r.mesh.f2e=r.f2e.data();
    common.meshsizes.ne0=ne; common.meshsizes.ne1=ne;
    common.meshsizes.nf=nf; common.meshsizes.nf0=nf;
    common.nnbsd=0; common.nelemsend=0; common.nelemrecv=0;
    common.nnbintf=0; common.nfacesend=0; common.nfacerecv=0;
    common.szinterfacefluxmap=ncu12;

    std::vector<dstype> v(N),AE(static_cast<std::size_t>(mtrace)*mtrace*ne,0.0);
    std::vector<dstype> ve(static_cast<std::size_t>(mtrace)*ne,0.0),we(ve.size(),0.0),w(N,0.0);
    for(Int i=0;i<N;++i) v[i]=0.021+0.0007*((i+17*worldRank)%97);
    std::vector<dstype> dummyReal(1,0.0); std::vector<Int> dummyInt(1,0);
    tempstruct tmp{}; tmp.buffsend=dummyReal.data(); tmp.buffrecv=dummyReal.data();
    tmp.tempi=dummyInt.data(); tmp.tempn=dummyReal.data(); tmp.tempg=dummyReal.data();
    hdgMatVec<dstype,Int>(w.data(),AE.data(),v.data(),ve.data(),we.data(),residual,
        r.app,r.mesh,common,tmp,0,0,&runtime);

    std::vector<dstype> veRef(ve.size(),0.0),weRef(we.size(),0.0),wRef(N,0.0);
    for(Int e=0;e<ne;++e) for(Int i=0;i<ndf;++i) for(Int c=0;c<ncu;++c)
        veRef[c+ncu*(i+ndf*e)]=v[c+ncu*r.elemcon[i+ndf*e]];

    const int record=4+ncu12*m.npf;
    std::vector<dstype> local;
    for(int direction=0;direction<2;++direction) {
        const nonmatchinginterface& host=nm.dir[direction];
        const auto& device=runtime.dir[direction];
        if(!host.isdonor) continue;
        for(Int slot=0;slot<host.nslots;++slot) {
            std::vector<long double> value(static_cast<std::size_t>(ncu12)*m.npf,0.0L);
            for(Int pair=0;pair<host.npairs;++pair) if(host.pairslot[pair]==slot) {
                const Int e=host.pairelem[pair];
                for(Int col=0;col<mtrace;++col) for(Int row=0;row<ncu12*m.npf;++row)
                    value[row]+=static_cast<long double>(device.Hi.data[row+
                        static_cast<std::size_t>(ncu12*m.npf)*(col+static_cast<std::size_t>(mtrace)*pair)])*
                        veRef[col+static_cast<std::size_t>(mtrace)*e];
            }
            local.push_back(direction); local.push_back(host.slotrank[slot]);
            local.push_back(host.slotface[slot]); local.push_back(worldRank);
            for(long double x:value) local.push_back(static_cast<dstype>(x));
        }
    }
    int size=0,count=static_cast<int>(local.size()); MPI_Comm_size(MPI_COMM_WORLD,&size);
    std::vector<int> counts(size),displs(size,0);
    MPI_Allgather(&count,1,MPI_INT,counts.data(),1,MPI_INT,MPI_COMM_WORLD);
    int total=0; for(int rank=0;rank<size;++rank) { displs[rank]=total; total+=counts[rank]; }
    std::vector<dstype> all(std::max(total,1));
    MPI_Allgatherv(local.data(),count,MPI_DOUBLE,all.data(),counts.data(),displs.data(),
        MPI_DOUBLE,MPI_COMM_WORLD);
    for(int offset=0;offset+record<=total;offset+=record) {
        const int direction=static_cast<int>(all[offset]);
        if(static_cast<int>(all[offset+1])!=worldRank) continue;
        const nonmatchinginterface& owner=nm.dir[direction];
        Int l=-1; const long globalFace=static_cast<long>(all[offset+2]);
        for(Int k=0;k<owner.nownfaces;++k) if(owner.ownfaceglobal[k]==globalFace) l=k;
        if(l<0) { std::printf("FAIL %s missing owner face rank %d\n",label,worldRank); ++failures; continue; }
        const Int encoded=r.intfaces[owner.ownface[l]],e=encoded/m.nfe,lf=encoded%m.nfe;
        for(Int i=0;i<m.npf;++i) for(Int c=0;c<ncu12;++c)
            weRef[r.interfacefluxmap[c]+ncu*(i+m.npf*(lf+m.nfe*e))]+=
                all[offset+4+c+ncu12*i];
    }
    for(Int e=0;e<ne;++e) for(Int i=0;i<ndf;++i) for(Int c=0;c<ncu;++c)
        wRef[c+ncu*r.elemcon[i+ndf*e]]+=weRef[c+ncu*(i+ndf*e)];
    dstype localError=0,scale=0;
    for(Int i=0;i<N;++i) { localError=std::max(localError,std::abs(w[i]-wRef[i]));
        scale=std::max(scale,std::abs(wRef[i])); }
    dstype localElementError=0;
    for(std::size_t i=0;i<we.size();++i)
        localElementError=std::max(localElementError,std::abs(we[i]-weRef[i]));
    dstype error=0,globalScale=0;
    MPI_Allreduce(&localError,&error,1,MPI_DOUBLE,MPI_MAX,MPI_COMM_WORLD);
    MPI_Allreduce(&scale,&globalScale,1,MPI_DOUBLE,MPI_MAX,MPI_COMM_WORLD);
    const dstype scaled=error/std::max<dstype>(1.0,globalScale);
    if(scaled>=1e-13) { std::printf("FAIL %s hdgMatVec rank %d error %.3e element %.3e\n",
        label,worldRank,scaled,localElementError); ++failures; }
    return scaled;
}

void setup_multi_rank_3d(SetupRank3D& r,SetupMaster3D& m,int model,int part,
        int modelRanks,dstype gap = 0.0,Int ncu=1,Int ncq=0,Int ncw=0,Int nfint=1,
        Int ne=2)
{
    r.problem.assign(35,0);
    r.problem[28]=1; r.problem[29]=1; r.problem[30]=2; r.problem[34]=1;
    r.nsize.assign(30,0); r.nsize[2]=35; r.nsize[14]=nfint;
    r.appdims.assign(30,0);
    r.appdims[AppNdims::nd]=3; r.appdims[AppNdims::nc]=ncu+ncq;
    r.appdims[AppNdims::ncu]=ncu; r.appdims[AppNdims::ncq]=ncq;
    r.appdims[AppNdims::ncw]=ncw; r.appdims[AppNdims::ncx]=3;
    r.meshdims.assign(20,0); r.meshdims[0]=3; r.meshdims[1]=ne; r.meshdims[4]=m.nfe;
    r.bf.assign(static_cast<std::size_t>(m.nfe)*ne,1);
    r.elempart.resize(ne); r.intfaces.resize(ne);
    r.interfacefluxmap.resize(nfint);
    for(Int c=0;c<nfint;++c) r.interfacefluxmap[c]=c;

    const Int i0=m.perm[0], i1=m.perm[1];
    dstype c[3]={m.xpe[i0],m.xpe[i0+m.npe],m.xpe[i0+2*m.npe]};
    dstype t1[3]={m.xpe[i1]-c[0],m.xpe[i1+m.npe]-c[1],m.xpe[i1+2*m.npe]-c[2]};
    dstype n1=std::sqrt(t1[0]*t1[0]+t1[1]*t1[1]+t1[2]*t1[2]);
    for(int d=0;d<3;++d) t1[d]/=n1;
    dstype t2[3]={0,0,0};
    for(Int q=2;q<m.npf;++q) {
        const Int iq=m.perm[q];
        dstype v[3]={m.xpe[iq]-c[0],m.xpe[iq+m.npe]-c[1],m.xpe[iq+2*m.npe]-c[2]};
        const dstype projection=v[0]*t1[0]+v[1]*t1[1]+v[2]*t1[2];
        for(int d=0;d<3;++d) t2[d]=v[d]-projection*t1[d];
        const dstype n2=std::sqrt(t2[0]*t2[0]+t2[1]*t2[1]+t2[2]*t2[2]);
        if(n2>1e-8) { for(int d=0;d<3;++d) t2[d]/=n2; break; }
    }
    dstype normal[3]={t1[1]*t2[2]-t1[2]*t2[1],
        t1[2]*t2[0]-t1[0]*t2[2],t1[0]*t2[1]-t1[1]*t2[0]};
    dstype centroid[3]={0,0,0};
    for(Int j=0;j<m.npe;++j)
        for(int d=0;d<3;++d) centroid[d]+=m.xpe[j+m.npe*d]/m.npe;
    const dstype inward=(centroid[0]-c[0])*normal[0]+(centroid[1]-c[1])*normal[1]+
        (centroid[2]-c[2])*normal[2];
    if(inward<0) for(int d=0;d<3;++d) normal[d]=-normal[d];

    r.xdg.assign(static_cast<std::size_t>(3)*m.npe*ne,0.0);
    const dstype side=model==0?-1.0:1.0;
    const dstype stagger=model==1?-0.5:0.0;
    for(Int e=0;e<ne;++e) {
        r.bf[m.nfe*e]=2;
        r.elempart[e]=ne*part+e;
        r.intfaces[e]=m.nfe*e;
        for(Int j=0;j<m.npe;++j) {
            const dstype v[3]={m.xpe[j]-c[0],m.xpe[j+m.npe]-c[1],m.xpe[j+2*m.npe]-c[2]};
            const dstype a=v[0]*t1[0]+v[1]*t1[1]+v[2]*t1[2];
            const dstype b=v[0]*t2[0]+v[1]*t2[1]+v[2]*t2[2];
            const dstype h=v[0]*normal[0]+v[1]*normal[1]+v[2]*normal[2];
            const std::size_t off=static_cast<std::size_t>(m.npe)*3*e;
            r.xdg[off+j]=0.5+(model==0?-0.5:0.5)*gap+side*h;
            r.xdg[off+j+m.npe]=2.0*part+e+stagger+a;
            r.xdg[off+j+2*m.npe]=b;
        }
    }

    r.app=appstruct(); r.master=masterstruct(); r.mesh=meshstruct(); r.sol=solstruct();
    r.app.problem=r.problem.data(); r.app.nsize=r.nsize.data(); r.app.ndims=r.appdims.data();
    r.app.interfacefluxmap=r.interfacefluxmap.data();
    r.master.ndims=m.ndims.data(); r.master.xpe=m.xpe.data(); r.master.xpf=m.xpf.data();
    r.master.gpf=m.gpf.data(); r.master.gwf=m.gwf.data(); r.master.shapfgt=m.shapfgt.data();
    r.mesh.ndims=r.meshdims.data(); r.mesh.bf=r.bf.data(); r.mesh.perm=m.perm.data();
    r.mesh.elempart=r.elempart.data(); r.mesh.szelempart=ne;
    r.mesh.intfaces=r.intfaces.data(); r.mesh.szintfaces=ne;
    r.sol.xdg=r.xdg.data();
    const Int ndf=m.npf*m.nfe;
    r.elemcon.resize(static_cast<std::size_t>(ndf)*ne);
    for(Int e=0;e<ne;++e)
        for(Int i=0;i<ndf;++i) r.elemcon[i+ndf*e]=i+ndf*e;
    r.mesh.elemcon=r.elemcon.data();
    (void)modelRanks;
}

void verify_owner_geometry(const SetupRank3D& r,const SetupMaster3D& m,
        int worldRank,int elemtype)
{
    using namespace exasim::nonmatching;
    const InterfaceFaceSet<dstype,Int> own = collect_own_interface_faces(
        r.app,r.master,r.mesh,r.sol,worldRank,0);
    DonorSearchResult<dstype,Int> points;
    own_quadrature_points(points,own,m.shapfgt.data(),m.ngf);
    std::vector<dstype> wJ,normal;
    owner_point_geometry(wJ,normal,points,own,m.shapfgt.data(),m.gwf.data());

    const Int nf=own.size(), ne=r.mesh.ndims[1], ndf=m.npf*m.nfe;
    const Int nall=m.ngf*m.nfe*ne;
    std::vector<dstype> xfn(static_cast<std::size_t>(ndf)*3*ne,0.0);
    std::vector<dstype> xg(static_cast<std::size_t>(nall)*3,0.0);
    std::vector<dstype> Jg(static_cast<std::size_t>(nall)*6,0.0);
    std::vector<dstype> jac(nall,0.0),nlg(static_cast<std::size_t>(nall)*3,0.0);
    GetElementFaceNodes(xfn.data(),r.sol.xdg,r.mesh.perm,ndf,3,m.npe,3,0,ne);
    Kokkos::fence();
    dstype* shapfgt=const_cast<dstype*>(m.shapfgt.data());
    Node2Gauss(0,xg.data(),xfn.data(),shapfgt,m.ngf,m.npf,
        m.nfe*ne*3,0);
    Node2Gauss(0,Jg.data(),xfn.data(),shapfgt+m.ngf*m.npf,
        m.ngf,m.npf,m.nfe*ne*3,0);
    Node2Gauss(0,Jg.data()+static_cast<std::size_t>(nall)*3,xfn.data(),
        shapfgt+2*m.ngf*m.npf,m.ngf,m.npf,m.nfe*ne*3,0);
    FaceGeom3D(jac.data(),nlg.data(),Jg.data(),nall);
    Kokkos::fence();

    dstype maxPoint=0,maxWeight=0,maxNormal=0,minDot=1;
    for(Int l=0;l<nf;++l)
        for(Int g=0;g<m.ngf;++g) {
            const Int p=g+m.ngf*l;
            const Int fullIndex=g+m.ngf*(own.lface[l]+m.nfe*own.elem[l]);
            for(Int d=0;d<3;++d)
                maxPoint=std::max(maxPoint,std::abs(points.x[p+points.npts*d]-
                    xg[fullIndex+nall*d]));
            const dstype referenceWeight=m.gwf[g]*jac[fullIndex];
            const dstype weightScale=std::max<dstype>(1,std::abs(referenceWeight));
            maxWeight=std::max(maxWeight,std::abs(wJ[p]-referenceWeight)/weightScale);
            dstype dot=0;
            for(Int d=0;d<3;++d) {
                const dstype reference=nlg[fullIndex+nall*d];
                maxNormal=std::max(maxNormal,std::abs(normal[p+points.npts*d]-reference));
                dot+=normal[p+points.npts*d]*reference;
            }
            minDot=std::min(minDot,dot);
        }
    if(maxPoint>2e-12 || maxWeight>2e-12 || maxNormal>2e-12 || !(minDot>0)) {
        std::printf("FAIL 3D owner geometry family %d rank %d point %.3e weight %.3e normal %.3e dot %.3e\n",
            elemtype,worldRank,maxPoint,maxWeight,maxNormal,minDot);
        ++failures;
    }
    if(worldRank==0)
        std::printf("3D owner geometry family %d: point %.3e weight %.3e normal %.3e min dot %.16f\n",
            elemtype,maxPoint,maxWeight,maxNormal,minDot);
}

template <class T>
void hash_bytes(unsigned long long& hash,const T* values,std::size_t count)
{
    const unsigned char* bytes=reinterpret_cast<const unsigned char*>(values);
    for(std::size_t i=0;i<count*sizeof(T);++i) { hash^=bytes[i]; hash*=1099511628211ULL; }
}

unsigned long long setup_hash(const nonmatchingdata& nm)
{
    unsigned long long hash=1469598103934665603ULL;
    hash_bytes(hash,&nm.interfacetype,1);
    for(int k=0;k<2;++k) {
        const auto& d=nm.dir[k];
        const Int fields[]={d.direction,d.isowner,d.isdonor,d.nd,d.npe,d.npf,d.nfe,d.ngf,
            d.ncu,d.ncq,d.ncu12,d.nownfaces,d.nrecvnb,d.npts,d.nslots,d.npairs,d.nsendnb,
            d.szRi,d.szHi,d.szsendbuf,d.szrecvbuf};
        hash_bytes(hash,fields,sizeof(fields)/sizeof(fields[0]));
        Int blocks=0; for(Int q=0;q<d.nrecvnb;++q) blocks+=d.recvcount[q];
        hash_bytes(hash,d.ownface,d.nownfaces); hash_bytes(hash,d.ownfaceglobal,d.nownfaces);
        hash_bytes(hash,d.recvnb,d.nrecvnb); hash_bytes(hash,d.recvcount,d.nrecvnb);
        hash_bytes(hash,d.recvface,blocks); hash_bytes(hash,d.pe,d.npts); hash_bytes(hash,d.pa,d.npts);
        hash_bytes(hash,d.pf,d.npts); hash_bytes(hash,d.pslot,d.npts); hash_bytes(hash,d.pg,d.npts);
        hash_bytes(hash,d.px,static_cast<std::size_t>(d.npts)*d.nd);
        hash_bytes(hash,d.pnl,static_cast<std::size_t>(d.npts)*d.nd); hash_bytes(hash,d.pwJ,d.npts);
        hash_bytes(hash,d.pxi,static_cast<std::size_t>(d.npts)*(d.nd-1));
        hash_bytes(hash,d.pzeta,static_cast<std::size_t>(d.npts)*d.nd);
        hash_bytes(hash,d.pphi,static_cast<std::size_t>(d.npts)*d.npe);
        hash_bytes(hash,d.pphibar,static_cast<std::size_t>(d.npts)*d.npe);
        hash_bytes(hash,d.ppsi,static_cast<std::size_t>(d.npts)*d.npf);
        hash_bytes(hash,d.pd,static_cast<std::size_t>(d.npts)*d.nd);
        if(d.ncq==0) hash_bytes(hash,d.pdphibar,static_cast<std::size_t>(d.npts)*d.nd*d.npe);
        hash_bytes(hash,d.slotrank,d.nslots); hash_bytes(hash,d.slotface,d.nslots);
        hash_bytes(hash,d.slotptr,d.nslots?d.nslots+1:0); hash_bytes(hash,d.pairslot,d.npairs);
        hash_bytes(hash,d.pairelem,d.npairs); hash_bytes(hash,d.pairptr,d.npairs?d.npairs+1:0);
    }
    return hash;
}

std::vector<std::pair<std::string,unsigned long long>> setup_field_hashes(const nonmatchingdata& nm)
{
    std::vector<std::pair<std::string,unsigned long long>> out;
    auto add=[&](const std::string& name,const auto* data,std::size_t count) {
        unsigned long long h=1469598103934665603ULL;
        hash_bytes(h,data,count); out.emplace_back(name,h);
    };
    for(int k=0;k<2;++k) {
        const auto& d=nm.dir[k]; const std::string p="d"+std::to_string(k)+".";
        Int blocks=0; for(Int q=0;q<d.nrecvnb;++q) blocks+=d.recvcount[q];
        add(p+"px",d.px,static_cast<std::size_t>(d.npts)*d.nd);
        add(p+"pnl",d.pnl,static_cast<std::size_t>(d.npts)*d.nd); add(p+"pwJ",d.pwJ,d.npts);
        add(p+"pxi",d.pxi,static_cast<std::size_t>(d.npts)*(d.nd-1));
        add(p+"pzeta",d.pzeta,static_cast<std::size_t>(d.npts)*d.nd);
        add(p+"pphi",d.pphi,static_cast<std::size_t>(d.npts)*d.npe);
        add(p+"pphibar",d.pphibar,static_cast<std::size_t>(d.npts)*d.npe);
        add(p+"ppsi",d.ppsi,static_cast<std::size_t>(d.npts)*d.npf);
        add(p+"pd",d.pd,static_cast<std::size_t>(d.npts)*d.nd);
        if(d.ncq==0) add(p+"pdphibar",d.pdphibar,static_cast<std::size_t>(d.npts)*d.nd*d.npe);
        add(p+"recvface",d.recvface,blocks); add(p+"slotface",d.slotface,d.nslots);
        add(p+"slotptr",d.slotptr,d.nslots?d.nslots+1:0);
        add(p+"pairptr",d.pairptr,d.npairs?d.npairs+1:0);
    }
    return out;
}

void setup_case(int elemtype,int p,int worldRank,int worldSize,dstype gap = 0.0)
{
    using namespace exasim::nonmatching;
    const int split=worldSize/2, model=worldRank<split?0:1;
    const int part=model==0?worldRank:worldRank-split;
    SetupMaster3D m=setup_master(elemtype,p);
    SetupRank3D r; setup_rank_3d(r,m,model,part,split,gap);
    nonmatchingdata nm;
    commonstruct common{};
    common.components.nc=1; common.components.ncu=1; common.components.ncq=0;
    common.components.ncx=3; common.meshsizes.ne=1; common.meshsizes.ne1=1;
    common.meshsizes.nfe=m.nfe;
    common.couplingparams.coupledboundarycondition=2;
    DonorSearchResult<dstype,Int> result;
    std::unique_ptr<NonmatchingRuntime<dstype,Int>> runtime;
    DonorSearchParams parameters;
    const bool ran=rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,common,
        worldSize,worldRank,model,nm,runtime,0,&result,parameters,true,
        static_cast<std::unique_ptr<OwnerTestData<dstype,Int>>*>(nullptr));
    if(!ran) { std::printf("FAIL 3D setup did not run family %d rank %d\n",elemtype,worldRank); ++failures; }
    const nonmatchinginterface& owner=nm.dir[model];
    const nonmatchinginterface& donor=nm.dir[1-model];
    auto require=[&](bool ok,const char* name) {
        if(!ok) { std::printf("FAIL 3D setup %s family %d rank %d\n",name,elemtype,worldRank); ++failures; }
    };
    verify_owner_geometry(r,m,worldRank,elemtype);
    require(owner.nownfaces==1,"owner face count");
    require(owner.nrecvnb==1 && owner.recvcount[0]==1 && owner.recvface[0]==0,"owner receive list");
    require(donor.npts==m.ngf && donor.nslots==1 && donor.npairs==1,"donor point/slot/pair counts");
    require(donor.npf==m.npf && donor.npe==m.npe && donor.nfe==m.nfe && donor.ngf==m.ngf,
        "role-local dimensions");
    require(donor.szRi==m.npf && donor.szHi==m.npf*m.npf*m.nfe,"work extents");
    require(donor.slotrank[0]==(model==0?part+split:part),"slot owner rank");
    require(donor.slotface[0]==m.nfe*part,"slot owner global face");
    const dstype eps=256*std::numeric_limits<dstype>::epsilon();
    for(Int q=0;q<donor.npts;++q) {
        dstype sumPhi=0,sumPhiBar=0,sumPsi=0,norm2=0,offset2=0;
        for(Int j=0;j<m.npe;++j) {
            sumPhi+=donor.pphi[j+m.npe*q];
            sumPhiBar+=donor.pphibar[j+m.npe*q];
        }
        for(Int j=0;j<m.npf;++j) sumPsi+=donor.ppsi[j+m.npf*q];
        for(Int d=0;d<3;++d) {
            norm2+=donor.pnl[q+donor.npts*d]*donor.pnl[q+donor.npts*d];
            offset2+=donor.pd[q+donor.npts*d]*donor.pd[q+donor.npts*d];
        }
        require(std::abs(sumPhi-1)<2e-12 && std::abs(sumPhiBar-1)<2e-12 &&
            std::abs(sumPsi-1)<2e-12,"partition of unity");
        require(std::abs(std::sqrt(norm2)-1)<2e-12 && donor.pwJ[q]>0,"owner geometry");
        if(gap==0) require(std::sqrt(offset2)<eps,"matching offset");
        else require(std::abs(std::sqrt(offset2)-gap)<2e-11,"OUTSIDE gap offset");
        require(donor.pg[q]>=0 && donor.pg[q]<m.ngf,"Gauss index");
    }
    require(donor.pdphibar!=nullptr,"q-free gradients");
    require(common.requests!=nullptr && common.statuses!=nullptr,"request capacity");
    if(runOperators) {
        auto& rd=runtime->dir[1-model];
        const auto v=rd.view;
        const Int n=m.npe, columns=m.npf*m.nfe, rows=m.npf;
        for(Int q=0;q<v.npts;++q) {
            rd.flux.data[q]=1.0+0.07*q;
            rd.fluxUdg.data[q]=0.2+0.01*q;
            rd.fluxUhg.data[q]=-0.15+0.02*q;
            for(Int d=0;d<3;++d) rd.pd.data[q+v.npts*d]=0.01*(d+1);
        }
        form_runtime_slot_residual(rd,r.master);
        std::vector<dstype> expectedRi(rows,0.0),expectedK(static_cast<std::size_t>(rows)*n,0.0);
        std::vector<dstype> expectedH(static_cast<std::size_t>(rows)*columns,0.0);
        for(Int i=0;i<rows;++i)
            for(Int q=0;q<v.npts;++q) {
                const dstype W=donor.pwJ[q]*m.shapfgt[donor.pg[q]+m.ngf*i];
                expectedRi[i]-=W*rd.flux.data[q];
                for(Int j=0;j<n;++j) {
                    dstype derivative=rd.fluxUdg.data[q]*donor.pphi[j+n*q];
                    for(Int d=0;d<3;++d)
                        derivative+=rd.fluxUhg.data[q]*rd.pd.data[q+v.npts*d]*
                            donor.pdphibar[j+n*(d+3*q)];
                    expectedK[i+rows*j]+=W*derivative;
                }
                for(Int j=0;j<m.npf;++j)
                    expectedH[i+rows*(j+m.npf*donor.pa[q])]+=
                        W*rd.fluxUhg.data[q]*donor.ppsi[j+m.npf*q];
            }
        for(Int i=0;i<rows;++i) require(std::abs(rd.Ri.data[i]-expectedRi[i])<5e-13,
            "slot residual reference");

        std::vector<dstype> F(static_cast<std::size_t>(n)*columns),Ru(n);
        for(std::size_t i=0;i<F.size();++i) F[i]=0.002*(1+static_cast<int>(i%17));
        for(Int i=0;i<n;++i) Ru[i]=0.003*(i+1);
        resstruct residual; residual.F=F.data(); residual.Ru=Ru.data();
        form_runtime_pairs(rd,r.master,residual,common,0,0);
        for(Int col=0;col<columns;++col)
            for(Int row=0;row<rows;++row) {
                dstype value=expectedH[row+rows*col];
                for(Int j=0;j<n;++j) value+=expectedK[row+rows*j]*F[j+n*col];
                require(std::abs(rd.Hi.data[row+rows*col]-value)<5e-13,
                    "condensed Hi reference");
                expectedH[row+rows*col]=value;
            }
        for(Int row=0;row<rows;++row) {
            dstype value=expectedRi[row];
            for(Int j=0;j<n;++j) value-=expectedK[row+rows*j]*Ru[j];
            require(std::abs(rd.Ri.data[row]-value)<5e-13,"condensed Ri reference");
        }

        std::vector<dstype> trace(columns),expectedProduct(rows,0.0);
        for(Int j=0;j<columns;++j) trace[j]=0.01*(j+1);
        for(Int row=0;row<rows;++row)
            for(Int col=0;col<columns;++col)
                expectedProduct[row]+=expectedH[row+rows*col]*trace[col];
        nonmatching_matvec_products(*runtime,trace.data(),columns,1,0,0);
        for(Int row=0;row<rows;++row)
            require(std::abs(rd.Ri.data[row]-expectedProduct[row])<5e-13,
                "matvec reference");

        auto& ro=runtime->dir[model];
        std::fill(ro.recvbuf.data,ro.recvbuf.data+ro.recvbuf.size,0.0);
        for(Int i=0;i<ro.recvbuf.size;++i) ro.recvbuf.data[i]=0.04*(i+1);
        std::vector<dstype> assembled(static_cast<std::size_t>(m.npf)*m.nfe,0.0);
        assemble_coupling_slot_owner(assembled.data(),*runtime,r.mesh,r.app,common);
        for(Int i=0;i<m.npf;++i) {
            const Int target=ro.view.ownerTarget[0]+i;
            require(std::abs(assembled[target]-ro.recvbuf.data[i])<5e-13,
                "owner assembly reference");
        }

        std::vector<dstype> u(n),du(n),uh(columns),duh(columns);
        for(Int j=0;j<n;++j) { u[j]=0.1+0.01*j; du[j]=0.02-0.001*j; }
        for(Int j=0;j<columns;++j) { uh[j]=-0.05+0.002*j; duh[j]=0.01+0.0003*j; }
        auto nonlinear_residual=[&](dstype epsilon,std::vector<dstype>& out) {
            out.assign(rows,0.0);
            for(Int q=0;q<v.npts;++q) {
                dstype uq=0,hq=0;
                for(Int j=0;j<n;++j) uq+=donor.pphi[j+n*q]*(u[j]+epsilon*du[j]);
                for(Int j=0;j<m.npf;++j)
                    hq+=donor.ppsi[j+m.npf*q]*(uh[j+m.npf*donor.pa[q]]+
                        epsilon*duh[j+m.npf*donor.pa[q]]);
                const dstype flux=uq*uq+std::sin(hq);
                for(Int i=0;i<rows;++i)
                    out[i]-=donor.pwJ[q]*m.shapfgt[donor.pg[q]+m.ngf*i]*flux;
            }
        };
        std::vector<dstype> base,perturbed,analytic(rows,0.0);
        nonlinear_residual(0,base);
        for(Int q=0;q<v.npts;++q) {
            dstype uq=0,hq=0,duq=0,dhq=0;
            for(Int j=0;j<n;++j) { uq+=donor.pphi[j+n*q]*u[j]; duq+=donor.pphi[j+n*q]*du[j]; }
            for(Int j=0;j<m.npf;++j) {
                const Int col=j+m.npf*donor.pa[q];
                hq+=donor.ppsi[j+m.npf*q]*uh[col]; dhq+=donor.ppsi[j+m.npf*q]*duh[col];
            }
            for(Int i=0;i<rows;++i)
                analytic[i]-=donor.pwJ[q]*m.shapfgt[donor.pg[q]+m.ngf*i]*
                    (2*uq*duq+std::cos(hq)*dhq);
        }
        dstype fdError=0;
        for(dstype epsilon: {1e-4,1e-5,1e-6}) {
            nonlinear_residual(epsilon,perturbed);
            for(Int i=0;i<rows;++i)
                fdError=std::max(fdError,std::abs((perturbed[i]-base[i])/epsilon-analytic[i]));
        }
        require(fdError<1e-6,"nonlinear directional finite difference");
        if(worldRank==0)
            std::printf("3D operators family %d p %d: reference %.3e FD %.3e\n",
                elemtype,p,5e-13,fdError);
    }
    if(runRebuild) {
        const unsigned long long original=setup_hash(nm);
        const auto originalFields=setup_field_hashes(nm);
        const std::vector<dstype> originalXdg=r.xdg;
        const long long allocations=runtime->allocations;
        for(Int j=0;j<m.npe;++j) r.xdg[j+m.npe]+=0.125;
        require(rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,common,
            worldSize,worldRank,model,nm,runtime,0,&result),"motion rebuild");
        nonmatchingdata fresh;
        std::unique_ptr<NonmatchingRuntime<dstype,Int>> freshRuntime;
        commonstruct freshCommon=common;
        freshCommon.requests=nullptr; freshCommon.statuses=nullptr;
        require(rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,freshCommon,
            worldSize,worldRank,model,fresh,freshRuntime,0,
            static_cast<DonorSearchResult<dstype,Int>*>(nullptr)),"fresh moved setup");
        require(setup_hash(nm)==setup_hash(fresh),"rebuilt/fresh cache identity");
        require(runtime->allocations==allocations && freshRuntime->allocations==allocations,
            "runtime allocation count stability");
        free_nonmatching_data(fresh); freshRuntime.reset();
        CPUFREE(freshCommon.requests); CPUFREE(freshCommon.statuses);

        std::copy(originalXdg.begin(),originalXdg.end(),r.xdg.begin());
        r.bf[0]=1;
        require(rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,common,
            worldSize,worldRank,model,nm,runtime,0,&result),"empty-interface rebuild");
        require(nm.dir[0].npts==0 && nm.dir[1].npts==0,"empty-interface cache");
        r.bf[0]=2;
        require(rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,common,
            worldSize,worldRank,model,nm,runtime,0,&result),"restored-interface rebuild");
        const unsigned long long restored=setup_hash(nm);
        if(restored!=original) {
            const auto restoredFields=setup_field_hashes(nm);
            for(std::size_t i=0;i<originalFields.size();++i)
                if(originalFields[i].second!=restoredFields[i].second)
                    std::printf("FAIL 3D rebuild field %s changed %016llx -> %016llx family %d rank %d\n",
                        originalFields[i].first.c_str(),originalFields[i].second,
                        restoredFields[i].second,elemtype,worldRank);
        }
        require(restored==original,"restored cache identity");
        require(runtime->allocations==allocations,"restored allocation count");
        if(worldRank==0)
            std::printf("3D rebuild family %d p %d: hash %016llx allocations %lld\n",
                elemtype,p,static_cast<unsigned long long>(original),allocations);
    }
    if(worldRank==0)
        std::printf("3D setup family %d p %d: points %d npf %d npe %d slots %d pairs %d\n",
            elemtype,p,int(donor.npts),int(m.npf),int(m.npe),int(donor.nslots),int(donor.npairs));
    free_nonmatching_data(nm);
    if(runRebuild) free_nonmatching_data(nm);
    CPUFREE(common.requests); CPUFREE(common.statuses);
}

void reject_setup_case(RejectMode mode,int worldRank,int worldSize)
{
    using namespace exasim::nonmatching;
    const int split=worldSize/2, model=worldRank<split?0:1;
    const int part=model==0?worldRank:worldRank-split;
    int elemtype=0, porder=2;
    if(mode==RejectMode::TetHex) elemtype=model;
    if(mode==RejectMode::Porder) porder=model==0?2:3;
    SetupMaster3D m=setup_master(elemtype,porder);
    SetupRank3D r; setup_rank_3d(r,m,model,part,split);

    if(mode==RejectMode::Quadrature && model==1) m.gwf[0]*=1.01;
    if(mode==RejectMode::RankConfig && worldRank==0) r.problem[34]=0;
    if(mode==RejectMode::Patch) {
        // Keep one nodal coordinate distinct enough for SurfaceNodalBasis,
        // but make the Bernstein collocation inversion reject the patch.
        const Int a=0,b=1;
        const dstype delta=8.0*std::numeric_limits<dstype>::epsilon();
        m.xpf[b]=m.xpf[a]+delta;
        m.xpf[b+m.npf]=m.xpf[a+m.npf]+delta;
    }

    // Review B1: rank-local D6 failures on ONE donor rank (the last world
    // rank, a model-2 rank). Every interface rank must report the same
    // diagnostic and exit nonzero; nothing may hang in a collective.
    const bool failingRank = worldRank == worldSize - 1;
    std::vector<dstype> corruptXpe;
    if(mode==RejectMode::VolumeBasis && failingRank) {
        // Duplicate a volume node: the D6 volume nodal basis Vandermonde is
        // singular. The element geometry (xdg) was built from the valid nodes.
        corruptXpe=m.xpe;
        for(int d=0;d<3;++d) corruptXpe[1+m.npe*d]=corruptXpe[0+m.npe*d];
    }
    if(mode==RejectMode::SingularMap && model==1) {
        // Collapse the donor element onto its interface face (x = 0.5 for
        // every node) on every model-2 rank. This makes the expected failure
        // independent of which donor partition owns a selected point. The
        // face geometry used by the search is unchanged and the closest points
        // are exact, but the volume map has an exactly zero normal derivative,
        // so the q-free gradient recovery is singular.
        for(Int j=0;j<m.npe;++j) r.xdg[j]=0.5;
    }

    // setup_rank_3d stored pointers into m before the test mutations above;
    // vector storage is unchanged, so only the values need refreshing here.
    r.master.ndims=m.ndims.data(); r.master.xpf=m.xpf.data();
    r.master.gpf=m.gpf.data(); r.master.gwf=m.gwf.data();
    if(!corruptXpe.empty()) r.master.xpe=corruptXpe.data();
    r.sol.xdg=r.xdg.data();
    nonmatchingdata nm;
    commonstruct common{};
    common.components.nc=1; common.components.ncu=1; common.components.ncq=0;
    common.components.ncx=3; common.meshsizes.ne=1; common.meshsizes.ne1=1;
    common.meshsizes.nfe=m.nfe;
    common.couplingparams.coupledboundarycondition=2;
    std::unique_ptr<NonmatchingRuntime<dstype,Int>> runtime;
    DonorSearchParams parameters;
    if(mode==RejectMode::Projection) parameters.maxProjectionIterations=0;
    const bool ran=rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,common,
        worldSize,worldRank,model,nm,runtime,0,
        static_cast<DonorSearchResult<dstype,Int>*>(nullptr),parameters);
    if(ran) {
        std::printf("UNEXPECTED: 3D expected-failure setup returned on rank %d\n",worldRank);
        free_nonmatching_data(nm); runtime.reset();
        CPUFREE(common.requests); CPUFREE(common.statuses);
        ++failures;
    }
}

void multi_setup_case(int elemtype,int p,int worldRank,int worldSize,dstype gap=0.0)
{
    using namespace exasim::nonmatching;
    const int split=worldSize/2, model=worldRank<split?0:1;
    const int part=model==0?worldRank:worldRank-split;
    SetupMaster3D m=setup_master(elemtype,p);
    SetupRank3D r; setup_multi_rank_3d(r,m,model,part,split,gap);
    const Int ndf=m.npf*m.nfe,ne=2;
    r.udg.assign(static_cast<std::size_t>(m.npe)*ne,0.0);
    r.uh.resize(static_cast<std::size_t>(ndf)*ne);
    for(std::size_t i=0;i<r.uh.size();++i) r.uh[i]=0.09+0.001*(i%41);
    r.sol.udg=r.udg.data(); r.sol.uh=r.uh.data();
    std::vector<dstype> tau(1,1.0),param(1,1.0),uinf(1,0.0);
    r.app.tau=tau.data(); r.app.physicsparam=param.data(); r.app.uinf=uinf.data();
    nonmatchingdata nm;
    commonstruct common{};
    common.components.nc=1; common.components.ncu=1; common.components.ncq=0;
    common.components.ncx=3; common.meshsizes.ne=2; common.meshsizes.ne1=2;
    common.meshsizes.nfe=m.nfe;
    common.grid.nd=3; common.grid.npe=m.npe; common.grid.npf=m.npf; common.grid.ngf=m.ngf;
    common.spatialScheme=1; common.szinterfacefluxmap=1;
    common.couplingparams.coupledcondition=1; common.couplingparams.coupledinterface=1;
    common.couplingparams.interfacetype=1;
    common.couplingparams.coupledboundarycondition=2;
    std::unique_ptr<NonmatchingRuntime<dstype,Int>> runtime;
    DonorSearchResult<dstype,Int> result;
    const bool ran=rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,common,
        worldSize,worldRank,model,nm,runtime,0,&result);
    if(!ran) { std::printf("FAIL 3D multi setup did not run family %d rank %d\n",elemtype,worldRank); ++failures; }
    verify_owner_geometry(r,m,worldRank,elemtype);

    const nonmatchinginterface& owner=nm.dir[model];
    const nonmatchinginterface& donor=nm.dir[1-model];
    int localMultiR=0,localMultiK=0;
    for(Int l=0;l<owner.nownfaces;++l) {
        int ranks=0; Int offset=0;
        for(Int q=0;q<owner.nrecvnb;++q) {
            bool serves=false;
            for(Int j=0;j<owner.recvcount[q];++j)
                serves=serves || owner.recvface[offset+j]==l;
            ranks+=serves?1:0;
            offset+=owner.recvcount[q];
        }
        localMultiR+=ranks>1?1:0;
    }
    for(Int s=0;s<donor.nslots;++s)
        localMultiK+=donor.slotptr[s+1]-donor.slotptr[s]>1?1:0;
    int globalMultiR=0,globalMultiK=0;
    MPI_Allreduce(&localMultiR,&globalMultiR,1,MPI_INT,MPI_SUM,MPI_COMM_WORLD);
    MPI_Allreduce(&localMultiK,&globalMultiK,1,MPI_INT,MPI_SUM,MPI_COMM_WORLD);
    if(worldSize>=4 && globalMultiR==0) {
        std::printf("FAIL 3D multi fixture has no owner face served by multiple donor ranks family %d rank %d\n",
            elemtype,worldRank); ++failures;
    }
    if(globalMultiK==0) {
        std::printf("FAIL 3D multi fixture has no slot with multiple donor elements family %d rank %d\n",
            elemtype,worldRank); ++failures;
    }
    if(worldRank==0)
        std::printf("3D multi family %d p %d: owner faces %d donor points %d slots %d pairs %d multiR %d multiK %d\n",
            elemtype,p,int(owner.nownfaces),int(donor.npts),int(donor.nslots),int(donor.npairs),
            globalMultiR,globalMultiK);

    if(runRebuild) {
        const Int oldPoints=nm.dir[1-model].npts,oldSlots=nm.dir[1-model].nslots;
        const Int oldPairs=nm.dir[1-model].npairs;
        const Int oldNeighbors=nm.dir[0].nsendnb+nm.dir[0].nrecvnb+
            nm.dir[1].nsendnb+nm.dir[1].nrecvnb;
        unsigned long long oldPointHash=1469598103934665603ULL;
        hash_bytes(oldPointHash,nm.dir[1-model].px,
            static_cast<std::size_t>(nm.dir[1-model].npts)*nm.dir[1-model].nd);
        const unsigned long long oldHash=setup_hash(nm);
        if(model==1)
            for(Int j=0;j<m.npe;++j)
                r.xdg[j+m.npe*0]+=0.70;
        if(!rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,common,
                worldSize,worldRank,model,nm,runtime,0,
                static_cast<DonorSearchResult<dstype,Int>*>(nullptr))) {
            std::printf("FAIL 3D multi motion rebuild family %d rank %d\n",elemtype,worldRank);
            ++failures;
        }
        unsigned long long newPointHash=1469598103934665603ULL;
        hash_bytes(newPointHash,nm.dir[1-model].px,
            static_cast<std::size_t>(nm.dir[1-model].npts)*nm.dir[1-model].nd);
        const Int newNeighbors=nm.dir[0].nsendnb+nm.dir[0].nrecvnb+
            nm.dir[1].nsendnb+nm.dir[1].nrecvnb;
        int changedLocal[5]={oldPointHash!=newPointHash,
            oldSlots!=nm.dir[1-model].nslots,oldPairs!=nm.dir[1-model].npairs,
            oldNeighbors!=newNeighbors,oldNeighbors!=newNeighbors};
        int changedGlobal[5]={0,0,0,0,0};
        MPI_Allreduce(changedLocal,changedGlobal,5,MPI_INT,MPI_MAX,MPI_COMM_WORLD);
        if(worldSize>=4 && std::find(changedGlobal,changedGlobal+5,0)!=changedGlobal+5) {
            std::printf("FAIL 3D multi rebuild change matrix family %d rank %d points %d slots %d pairs %d neighbors %d requests %d\n",
                elemtype,worldRank,changedGlobal[0],changedGlobal[1],changedGlobal[2],
                changedGlobal[3],changedGlobal[4]); ++failures;
        }

        nonmatchingdata fresh;
        std::unique_ptr<NonmatchingRuntime<dstype,Int>> freshRuntime;
        commonstruct freshCommon=common; freshCommon.requests=nullptr; freshCommon.statuses=nullptr;
        rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,freshCommon,
            worldSize,worldRank,model,fresh,freshRuntime,0,
            static_cast<DonorSearchResult<dstype,Int>*>(nullptr));
        if(setup_hash(nm)!=setup_hash(fresh)) {
            std::printf("FAIL 3D multi rebuilt/fresh cache family %d rank %d\n",elemtype,worldRank);
            ++failures;
        }

        std::vector<dstype> F(static_cast<std::size_t>(m.npe)*ndf*ne,0.0),
            Ru(static_cast<std::size_t>(m.npe)*ne,0.0);
        resstruct rebuiltResidual{},freshResidual{};
        rebuiltResidual.F=F.data(); rebuiltResidual.Ru=Ru.data();
        freshResidual.F=F.data(); freshResidual.Ru=Ru.data(); tempstruct couplingTmp{};
        compute_nonmatching_coupling<OrientationCoupled3D>(*runtime,r.sol,rebuiltResidual,
            r.app,r.master,r.mesh,couplingTmp,common,0,true,0);
        compute_nonmatching_coupling<OrientationCoupled3D>(*freshRuntime,r.sol,freshResidual,
            r.app,r.master,r.mesh,couplingTmp,freshCommon,0,true,0);
        dstype rebuiltResidualError=0,rebuiltJacobianError=0;
        for(int direction=0;direction<2;++direction) {
            const auto& a=runtime->dir[direction]; const auto& b=freshRuntime->dir[direction];
            for(Int i=0;i<a.Ri.size;++i)
                rebuiltResidualError=std::max(rebuiltResidualError,std::abs(a.Ri.data[i]-b.Ri.data[i]));
            for(Int i=0;i<a.Hi.size;++i)
                rebuiltJacobianError=std::max(rebuiltJacobianError,std::abs(a.Hi.data[i]-b.Hi.data[i]));
        }
        const dstype rebuiltMatvecError=verify_runtime_matvec("rebuilt",r,m,common,
            rebuiltResidual,nm,*runtime,1,1,worldRank);
        const dstype freshMatvecError=verify_runtime_matvec("fresh",r,m,freshCommon,
            freshResidual,fresh,*freshRuntime,1,1,worldRank);
        if(rebuiltResidualError>5e-13 || rebuiltJacobianError>5e-13 ||
                rebuiltMatvecError>=1e-13 || freshMatvecError>=1e-13) {
            std::printf("FAIL 3D rebuilt/fresh operators family %d rank %d residual %.3e Jacobian %.3e matvec %.3e/%.3e\n",
                elemtype,worldRank,rebuiltResidualError,rebuiltJacobianError,
                rebuiltMatvecError,freshMatvecError); ++failures;
        }

        auto exercise=[&](NonmatchingRuntime<dstype,Int>& rt,commonstruct& cm) {
            for(int direction=0;direction<2;++direction) {
                auto& d=rt.dir[direction];
                for(Int i=0;i<d.Ri.size;++i) d.Ri.data[i]=1000.0*worldRank+0.01*(i+1);
            }
            Int request=0;
            begin_coupling_slot_exchange(rt,cm,request);
            if(request>0) MPI_Waitall(request,cm.requests,cm.statuses);
            std::vector<dstype> result(static_cast<std::size_t>(m.npf)*m.nfe*2,0.0);
            assemble_coupling_slot_owner(result.data(),rt,r.mesh,r.app,cm);
            return result;
        };
        const auto rebuiltResult=exercise(*runtime,common);
        const auto freshResult=exercise(*freshRuntime,freshCommon);
        if(rebuiltResult!=freshResult) {
            std::printf("FAIL 3D multi rebuilt/fresh exchange family %d rank %d\n",elemtype,worldRank);
            ++failures;
        }
        const long long allocationCount=runtime->allocations;
        for(int repeat=0;repeat<3;++repeat) (void)exercise(*runtime,common);
        if(runtime->allocations!=allocationCount) {
            std::printf("FAIL 3D multi repeated exchange allocation growth family %d rank %d\n",
                elemtype,worldRank); ++failures;
        }

        const unsigned long long usableHash=setup_hash(nm);
        DonorSearchParams failedProjection;
        failedProjection.maxProjectionIterations=0;
        bool projectionRejected=false;
        try {
            rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,common,
                worldSize,worldRank,model,nm,runtime,0,
                static_cast<DonorSearchResult<dstype,Int>*>(nullptr),failedProjection);
        }
        catch(const UniformSetupError&) { projectionRejected=true; }
        int allProjectionRejected=0,projectionRejectedInt=projectionRejected?1:0;
        MPI_Allreduce(&projectionRejectedInt,&allProjectionRejected,1,MPI_INT,MPI_MIN,
            MPI_COMM_WORLD);
        if(!allProjectionRejected || setup_hash(nm)!=usableHash) {
            std::printf("FAIL 3D multi projection-failure rollback family %d rank %d\n",
                elemtype,worldRank);
            ++failures;
        }

        const dstype saved=m.xpf[1]; m.xpf[1]=m.xpf[0];
        bool rejected=false;
        try {
            rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,common,
                worldSize,worldRank,model,nm,runtime,0,
                static_cast<DonorSearchResult<dstype,Int>*>(nullptr));
        }
        catch(const std::runtime_error&) { rejected=true; }
        m.xpf[1]=saved;
        int allRejected=0,rejectedInt=rejected?1:0;
        MPI_Allreduce(&rejectedInt,&allRejected,1,MPI_INT,MPI_MIN,MPI_COMM_WORLD);
        if(!allRejected || setup_hash(nm)!=usableHash) {
            std::printf("FAIL 3D multi failed-rebuild rollback family %d rank %d\n",elemtype,worldRank);
            ++failures;
        }
        (void)exercise(*runtime,common);
        if(worldRank==0)
            std::printf("3D multi rebuild family %d: old hash %016llx changes %d/%d/%d/%d/%d allocations %lld\n",
                elemtype,oldHash,changedGlobal[0],changedGlobal[1],changedGlobal[2],
                changedGlobal[3],changedGlobal[4],allocationCount);
        free_nonmatching_data(fresh); freshRuntime.reset();
        CPUFREE(freshCommon.requests); CPUFREE(freshCommon.statuses);
    }
    free_nonmatching_data(nm); runtime.reset();
    if(runRebuild) free_nonmatching_data(nm);
    CPUFREE(common.requests); CPUFREE(common.statuses);
}

template <class V,class I>
std::size_t runtime_buffer_bytes(const exasim::nonmatching::RuntimeBuffer<V,I>& b)
{
    return static_cast<std::size_t>(b.capacity)*sizeof(V);
}

std::size_t runtime_direction_bytes(const exasim::nonmatching::NonmatchingRuntimeDirection<dstype,Int>& d)
{
    std::size_t bytes=0;
#define ADD_RUNTIME_BUFFER(name) bytes+=runtime_buffer_bytes(d.name)
    ADD_RUNTIME_BUFFER(pe); ADD_RUNTIME_BUFFER(pa); ADD_RUNTIME_BUFFER(pslot); ADD_RUNTIME_BUFFER(pg);
    ADD_RUNTIME_BUFFER(slotptr); ADD_RUNTIME_BUFFER(pairslot); ADD_RUNTIME_BUFFER(pairelem);
    ADD_RUNTIME_BUFFER(pairptr); ADD_RUNTIME_BUFFER(recvface); ADD_RUNTIME_BUFFER(ownface);
    ADD_RUNTIME_BUFFER(pairSlotPtr); ADD_RUNTIME_BUFFER(ownerTarget); ADD_RUNTIME_BUFFER(faceBlockPtr);
    ADD_RUNTIME_BUFFER(faceBlocks); ADD_RUNTIME_BUFFER(px); ADD_RUNTIME_BUFFER(pnl);
    ADD_RUNTIME_BUFFER(pwJ); ADD_RUNTIME_BUFFER(pphi); ADD_RUNTIME_BUFFER(pphibar);
    ADD_RUNTIME_BUFFER(ppsi); ADD_RUNTIME_BUFFER(pd); ADD_RUNTIME_BUFFER(pdphibar);
    ADD_RUNTIME_BUFFER(ptest); ADD_RUNTIME_BUFFER(Ri); ADD_RUNTIME_BUFFER(Hi);
    ADD_RUNTIME_BUFFER(recvbuf); ADD_RUNTIME_BUFFER(x); ADD_RUNTIME_BUFFER(udg);
    ADD_RUNTIME_BUFFER(odg); ADD_RUNTIME_BUFFER(wdg); ADD_RUNTIME_BUFFER(uhg);
    ADD_RUNTIME_BUFFER(nl); ADD_RUNTIME_BUFFER(wsrc); ADD_RUNTIME_BUFFER(flux);
    ADD_RUNTIME_BUFFER(fluxUdg); ADD_RUNTIME_BUFFER(fluxWdg); ADD_RUNTIME_BUFFER(fluxUhg);
    ADD_RUNTIME_BUFFER(wdgUdg); ADD_RUNTIME_BUFFER(equationUdg); ADD_RUNTIME_BUFFER(wScratch);
    ADD_RUNTIME_BUFFER(iScratch); ADD_RUNTIME_BUFFER(K); ADD_RUNTIME_BUFFER(G);
    ADD_RUNTIME_BUFFER(Cpair); ADD_RUNTIME_BUFFER(Epair); ADD_RUNTIME_BUFFER(pairResidual);
    ADD_RUNTIME_BUFFER(vpair); ADD_RUNTIME_BUFFER(rpair); ADD_RUNTIME_BUFFER(Fpair);
    ADD_RUNTIME_BUFFER(Rupair);
#undef ADD_RUNTIME_BUFFER
    bytes+=(d.sendnb.capacity()+d.sendcount.capacity()+d.recvnb.capacity()+d.recvcount.capacity())*
        sizeof(Int);
    return bytes;
}

std::size_t host_direction_bytes(const nonmatchinginterface& d)
{
    Int recvBlocks=0; for(Int q=0;q<d.nrecvnb;++q) recvBlocks+=d.recvcount[q];
    return sizeof(Int)*(static_cast<std::size_t>(d.nownfaces)*2+d.nrecvnb*2+recvBlocks+
        static_cast<std::size_t>(d.npts)*5+(d.nslots?d.nslots+1:0)+2*d.nslots+
        2*d.npairs+(d.npairs?d.npairs+1:0)+d.nsendnb*2)+
        sizeof(dstype)*(static_cast<std::size_t>(d.npts)*(3*d.nd+1+d.npe*2+d.npf+
        (d.ncq==0?d.nd*d.npe:0))+d.szRi+d.szHi+d.szsendbuf+d.szrecvbuf);
}

void cost_runtime_case(int elemtype,int worldRank,int worldSize,Int ne=2)
{
    using namespace exasim::nonmatching;
    const Int split=worldSize/2,model=worldRank<split?0:1,part=model==0?worldRank:worldRank-split;
    SetupMaster3D m=setup_master(elemtype,4);
    SetupRank3D r; setup_multi_rank_3d(r,m,model,part,split,0.0,1,0,0,1,ne);
    commonstruct common{};
    common.components.nc=1; common.components.ncu=1; common.components.ncq=0;
    common.components.ncx=3; common.meshsizes.ne=ne; common.meshsizes.ne0=ne;
    common.meshsizes.ne1=ne; common.meshsizes.nfe=m.nfe;
    common.couplingparams.coupledboundarycondition=2;
    nonmatchingdata nm; std::unique_ptr<NonmatchingRuntime<dstype,Int>> runtime;
    MPI_Barrier(MPI_COMM_WORLD);
    const double begin=MPI_Wtime();
    rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,common,worldSize,worldRank,
        model,nm,runtime,0,static_cast<DonorSearchResult<dstype,Int>*>(nullptr));
    const double coldSetupSeconds=MPI_Wtime()-begin;

    auto median=[&](auto operation) {
        std::vector<double> times;
        times.reserve(7);
        for(int repeat=0;repeat<8;++repeat) {
            MPI_Barrier(MPI_COMM_WORLD);
            const double t0=MPI_Wtime(); operation(); Kokkos::fence();
            const double elapsed=MPI_Wtime()-t0;
            if(repeat>0) times.push_back(elapsed);
        }
        std::sort(times.begin(),times.end()); return times[times.size()/2];
    };

    std::vector<double> hostSetupTimes,searchTimes;
    SearchStatistics measuredStatistics;
    hostSetupTimes.reserve(7); searchTimes.reserve(7);
    for(int repeat=0;repeat<8;++repeat) {
        nonmatchingdata candidate;
        SearchStatistics statistics;
        MPI_Barrier(MPI_COMM_WORLD);
        const double t0=MPI_Wtime();
        setup_nonmatching_interface(r.app,r.master,r.mesh,r.sol,worldSize,worldRank,
            model,candidate,static_cast<DonorSearchResult<dstype,Int>*>(nullptr),
            DonorSearchParams(),true,&statistics);
        const double elapsed=MPI_Wtime()-t0;
        if(repeat>0) {
            hostSetupTimes.push_back(elapsed);
            searchTimes.push_back(statistics.searchSeconds);
            measuredStatistics=statistics;
        }
        free_nonmatching_data(candidate);
    }
    std::sort(hostSetupTimes.begin(),hostSetupTimes.end());
    std::sort(searchTimes.begin(),searchTimes.end());
    const double hostSetupSeconds=hostSetupTimes[hostSetupTimes.size()/2];
    const double searchSeconds=searchTimes[searchTimes.size()/2];

    const double transactionalSetupSeconds=median([&] {
        nonmatchingdata candidate;
        commonstruct candidateCommon=common;
        candidateCommon.requests=nullptr; candidateCommon.statuses=nullptr;
        std::unique_ptr<NonmatchingRuntime<dstype,Int>> candidateRuntime;
        rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,candidateCommon,
            worldSize,worldRank,model,candidate,candidateRuntime,0,
            static_cast<DonorSearchResult<dstype,Int>*>(nullptr));
        free_nonmatching_data(candidate); candidateRuntime.reset();
        CPUFREE(candidateCommon.requests); CPUFREE(candidateCommon.statuses);
    });
    auto& d=runtime->dir[1-model];
    for(Int q=0;q<d.view.npts;++q) {
        d.flux.data[q]=0.4+0.001*q; d.fluxUdg.data[q]=0.2; d.fluxUhg.data[q]=-0.1;
    }
    const Int n=m.npe,mtrace=m.npf*m.nfe;
    std::vector<dstype> F(static_cast<std::size_t>(n)*mtrace*2,0.001),Ru(static_cast<std::size_t>(n)*2,0.002);
    std::vector<dstype> trace(static_cast<std::size_t>(mtrace)*2,0.03);
    resstruct residual{}; residual.F=F.data(); residual.Ru=Ru.data();
    const double residualSeconds=median([&]{ form_runtime_slot_residual(d,r.master); });
    const double jacobianSeconds=median([&]{ form_runtime_pairs(d,r.master,residual,common,0,0); });
    const double matvecSeconds=median([&]{ nonmatching_matvec_products(*runtime,trace.data(),mtrace,2,0,0); });
    std::size_t hostBytes=0,runtimeBytes=0,messageBytes=0;
    for(int k=0;k<2;++k) {
        hostBytes+=host_direction_bytes(nm.dir[k]);
        runtimeBytes+=runtime_direction_bytes(runtime->dir[k]);
        messageBytes+=static_cast<std::size_t>(nm.dir[k].szsendbuf)*sizeof(dstype);
    }
    long long points=nm.dir[1-model].npts;
    double values[9]={coldSetupSeconds,hostSetupSeconds,searchSeconds,
        transactionalSetupSeconds,residualSeconds,jacobianSeconds,matvecSeconds,
        static_cast<double>(hostBytes),static_cast<double>(runtimeBytes)};
    double maxima[9]; long long totalPoints=0,maxPoints=0,totalMessages=0;
    long long searchSums[4]={measuredStatistics.facesEvaluated,
        measuredStatistics.facesPruned,measuredStatistics.projectionStarts,
        measuredStatistics.projectionIterations};
    long long globalSearchSums[4]={0,0,0,0};
    long long peakFaces=measuredStatistics.maxFacesPerPoint,globalPeakFaces=0;
    MPI_Reduce(values,maxima,9,MPI_DOUBLE,MPI_MAX,0,MPI_COMM_WORLD);
    MPI_Reduce(&points,&totalPoints,1,MPI_LONG_LONG,MPI_SUM,0,MPI_COMM_WORLD);
    MPI_Reduce(&points,&maxPoints,1,MPI_LONG_LONG,MPI_MAX,0,MPI_COMM_WORLD);
    long long localMessages=static_cast<long long>(messageBytes);
    MPI_Reduce(&localMessages,&totalMessages,1,MPI_LONG_LONG,MPI_SUM,0,MPI_COMM_WORLD);
    MPI_Reduce(searchSums,globalSearchSums,4,MPI_LONG_LONG,MPI_SUM,0,MPI_COMM_WORLD);
    MPI_Reduce(&peakFaces,&globalPeakFaces,1,MPI_LONG_LONG,MPI_MAX,0,MPI_COMM_WORLD);
    if(worldRank==0) {
        const double gateSecondsPerPoint=maxima[3]/std::max<long long>(1,totalPoints);
        const double callsPerPoint=static_cast<double>(globalSearchSums[0])/
            std::max<long long>(1,totalPoints);
        if(gateSecondsPerPoint>2.5e-4) {
            std::printf("FAIL 3D COST setup gate family %d %.6e > 2.5e-4\n",
                elemtype,gateSecondsPerPoint); ++failures;
        }
        if(globalSearchSums[0]<=0 || globalSearchSums[2]<globalSearchSums[0] ||
           globalSearchSums[3]<globalSearchSums[2] || globalPeakFaces<1) {
            std::printf("FAIL 3D COST invalid multi-start counters family %d faces %lld starts %lld iterations %lld peak %lld\n",
                elemtype,globalSearchSums[0],globalSearchSums[2],globalSearchSums[3],globalPeakFaces); ++failures;
        }
        // The 1+1 fixture performs two face evaluations per global point.
        // Four ranks/model may perform at most twice that work per point.
        if(worldSize==8 && callsPerPoint>4.0) {
            std::printf("FAIL 3D COST face-evaluation scaling family %d %.6f > 4\n",
                elemtype,callsPerPoint); ++failures;
        }
        std::printf("3D COST family %d ranks/model %d elements/rank %d boxes %d points-global %lld points-critical %lld cold %.6e host-setup %.6e search %.6e transaction %.6e gate/point %.6e critical/point %.6e residual %.6e jacobian %.6e matvec %.6e message %lld host %.0f runtime %.0f projected-faces %lld pruned-faces %lld starts %lld iterations %lld peak-faces %lld\n",
            elemtype,int(split),int(ne),int(worldSize),totalPoints,maxPoints,maxima[0],maxima[1],maxima[2],
            maxima[3],maxima[3]/std::max<long long>(1,totalPoints),
            maxima[3]/std::max<long long>(1,maxPoints),maxima[4],maxima[5],maxima[6],
            totalMessages,maxima[7],maxima[8],globalSearchSums[0],globalSearchSums[1],
            globalSearchSums[2],globalSearchSums[3],globalPeakFaces);
    }
    free_nonmatching_data(nm); runtime.reset(); CPUFREE(common.requests); CPUFREE(common.statuses);
}

template <class Model>
void model_operator_case(const char* name,int elemtype,int p,int worldRank,int worldSize,dstype gap=0.0)
{
    using namespace exasim::nonmatching;
    const Int split=worldSize/2,model=worldRank<split?0:1,part=model==0?worldRank:worldRank-split;
    const Int ne=2,ncu=Model::ncu,ncq=Model::ncq,nc=ncu+ncq,ncu12=Model::nfint;
    SetupMaster3D m=setup_master(elemtype,p);
    SetupRank3D r;
    setup_multi_rank_3d(r,m,model,part,split,gap,ncu,ncq,Model::ncw,ncu12);
    const Int n=m.npe*ncu,ndf=m.npf*m.nfe,mtrace=ndf*ncu,m12=m.npf*ncu12;

    r.udg.resize(static_cast<std::size_t>(m.npe)*nc*ne);
    r.uh.resize(static_cast<std::size_t>(ncu)*ndf*ne);
    for(std::size_t i=0;i<r.udg.size();++i) r.udg[i]=0.17+0.001*(1+int(i%211));
    for(std::size_t i=0;i<r.uh.size();++i) r.uh[i]=-0.09+0.0015*(1+int(i%173));
    r.sol.udg=r.udg.data(); r.sol.uh=r.uh.data();
    if constexpr (Model::ncw>0) {
        r.wdg.assign(static_cast<std::size_t>(m.npe)*Model::ncw*ne,0.0);
        r.wsrc.assign(r.wdg.size(),0.0);
        r.sol.wdg=r.wdg.data(); r.sol.wsrc=r.wsrc.data();
    }

    std::vector<dstype> tau(ncu,1.0),param(1,1.0),uinf(1,0.0);
    r.app.tau=tau.data(); r.app.physicsparam=param.data(); r.app.uinf=uinf.data();
    r.app.materialdb_nprop=0;
    commonstruct common{};
    common.components.nc=nc; common.components.ncu=ncu; common.components.ncq=ncq;
    common.components.ncx=3; common.components.ncw=Model::ncw;
    common.grid.nd=3; common.grid.npe=m.npe; common.grid.npf=m.npf; common.grid.ngf=m.ngf;
    common.meshsizes.ne=ne; common.meshsizes.ne0=ne; common.meshsizes.ne1=ne;
    common.meshsizes.nfe=m.nfe; common.spatialScheme=1;
    common.couplingparams.coupledboundarycondition=2;
    common.couplingparams.coupledcondition=1; common.couplingparams.coupledinterface=1;
    common.couplingparams.interfacetype=1;
    common.timeparams.wave=0; common.timeparams.dae_alpha=0; common.timeparams.dae_beta=0;
    common.timestate.dtfactor=1; common.timestate.time=0;

    nonmatchingdata nm;
    std::unique_ptr<NonmatchingRuntime<dstype,Int>> runtime;
    if(!rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,common,worldSize,worldRank,
            model,nm,runtime,0,static_cast<DonorSearchResult<dstype,Int>*>(nullptr))) {
        std::printf("FAIL 3D model operator setup %s family %d rank %d\n",name,elemtype,worldRank);
        ++failures; return;
    }

    std::vector<dstype> C(static_cast<std::size_t>(m.npe)*m.npe*ne*3,0.0);
    std::vector<dstype> E(static_cast<std::size_t>(m.npe)*ndf*ne*3,0.0);
    std::vector<dstype> F(static_cast<std::size_t>(n)*mtrace*ne,0.0);
    std::vector<dstype> Ru(static_cast<std::size_t>(n)*ne,0.0);
    for(Int d=0;d<3;++d) for(Int e=0;e<ne;++e) {
        for(Int j=0;j<m.npe;++j) for(Int k=0;k<m.npe;++k)
            C[k+m.npe*j+static_cast<std::size_t>(m.npe)*m.npe*(e+ne*d)]=
                (j==k?0.07*(d+1):0.0002*(1+(j+3*k+5*d)%11));
        for(Int j=0;j<ndf;++j) for(Int k=0;k<m.npe;++k)
            E[k+m.npe*j+static_cast<std::size_t>(m.npe)*ndf*(e+ne*d)]=
                0.00015*(1+(k+2*j+7*d)%13);
    }
    for(Int e=0;e<ne;++e) {
        for(Int col=0;col<mtrace;++col) for(Int row=0;row<n;++row)
            F[row+n*(col+static_cast<std::size_t>(mtrace)*e)]=
                0.0001*(1+(row+3*col+5*e)%17);
        for(Int row=0;row<n;++row) Ru[row+n*e]=0.0003*(1+(row+7*e)%19);
    }
    resstruct residual{}; residual.C=C.data(); residual.E=E.data();
    residual.F=F.data(); residual.Ru=Ru.data();
    tempstruct tmp{};
    compute_nonmatching_coupling<Model>(*runtime,r.sol,residual,r.app,r.master,r.mesh,tmp,common,
        0,true,0);

    auto& rd=runtime->dir[1-model];
    const auto& donor=nm.dir[1-model];
    dstype fluxError=0,jacError=0,wError=0,wJacError=0;
    for(Int q=0;q<rd.view.npts;++q) {
        dstype f[2]={0,0}; std::vector<dstype> juq(static_cast<std::size_t>(ncu12)*nc,0.0);
        std::vector<dstype> juh(static_cast<std::size_t>(ncu12)*ncu,0.0);
        // Point-first production arrays are strided; gather explicitly before
        // calling the independent point model.
        dstype uqv[8]={0},uhv[2]={0},wv[2]={0};
        for(Int c=0;c<nc;++c) uqv[c]=rd.udg.data[q+rd.view.npts*c];
        for(Int c=0;c<ncu;++c) uhv[c]=rd.uhg.data[q+rd.view.npts*c];
        if constexpr (Model::ncw>0) for(Int c=0;c<Model::ncw;++c)
            wv[c]=rd.wdg.data[q+rd.view.npts*c];
        Model::fint(f,0,nullptr,uqv,nullptr,wv,uhv,nullptr,nullptr,nullptr,nullptr,0.0);
        Model::fint_jac_uq(juq.data(),0,nullptr,uqv,nullptr,wv,uhv,nullptr,nullptr,nullptr,nullptr,0.0);
        Model::fint_jac_uh(juh.data(),0,nullptr,uqv,nullptr,wv,uhv,nullptr,nullptr,nullptr,nullptr,0.0);
        if constexpr (Model::ncw>0) {
            dstype z[8]; for(Int c=0;c<nc;++c) z[c]=c<ncu?uhv[c]:uqv[c];
            const dstype A=std::sin(z[0])+z[2]*z[3];
            const dstype B=z[1]*z[1]+0.5*z[4]+0.5;
            dstype expectedW[2]={(A+0.3*B)/1.06,0.0};
            expectedW[1]=B-0.2*expectedW[0];
            for(Int k=0;k<2;++k) wError=std::max(wError,std::abs(wv[k]-expectedW[k]));
            dstype fw[4]={0};
            Model::fint_jac_w(fw,0,nullptr,uqv,nullptr,wv,uhv,nullptr,nullptr,nullptr,nullptr,0.0);
            for(Int c=0;c<nc;++c) {
                dstype dA=0,dB=0;
                if(c==0) dA=std::cos(z[0]); if(c==2) dA=z[3]; if(c==3) dA=z[2];
                if(c==1) dB=2.0*z[1]; if(c==4) dB=0.5;
                dstype dw[2]={(dA+0.3*dB)/1.06,0.0};
                dw[1]=dB-0.2*dw[0];
                for(Int k=0;k<2;++k)
                    wJacError=std::max(wJacError,std::abs(rd.wdgUdg.data[q+
                        rd.view.npts*(k+2*c)]-dw[k]));
                for(Int out=0;out<ncu12;++out) {
                    dstype chain=0; for(Int k=0;k<2;++k) chain+=fw[out+ncu12*k]*dw[k];
                    if(c<ncu) juh[out+ncu12*c]+=chain;
                    else juq[out+ncu12*c]+=chain;
                }
            }
        }
        for(Int out=0;out<ncu12;++out) {
            fluxError=std::max(fluxError,std::abs(rd.flux.data[q+rd.view.npts*out]-f[out]));
            for(Int c=0;c<nc;++c)
                jacError=std::max(jacError,std::abs(rd.fluxUdg.data[q+rd.view.npts*(out+ncu12*c)]-
                    juq[out+ncu12*c]));
            for(Int c=0;c<ncu;++c)
                jacError=std::max(jacError,std::abs(rd.fluxUhg.data[q+rd.view.npts*(out+ncu12*c)]-
                    juh[out+ncu12*c]));
        }
    }

    dstype fdError=0;
    if constexpr (Model::ncw>0) {
        const dstype eps=2.0e-6;
        std::vector<dstype> baseUdg=r.udg,baseUh=r.uh,plus(rd.flux.size),minus(rd.flux.size);
        dstype du[8],duh[2];
        for(Int c=0;c<nc;++c) du[c]=0.013*(c+1);
        for(Int c=0;c<ncu;++c) duh[c]=-0.017*(c+1);
        auto perturb=[&](dstype sign) {
            r.udg=baseUdg; r.uh=baseUh;
            for(Int e=0;e<ne;++e) for(Int c=0;c<nc;++c) for(Int j=0;j<m.npe;++j)
                r.udg[j+m.npe*(c+nc*e)]+=sign*eps*du[c];
            for(Int e=0;e<ne;++e) for(Int i=0;i<ndf;++i) for(Int c=0;c<ncu;++c)
                r.uh[c+ncu*(i+ndf*e)]+=sign*eps*duh[c];
            r.sol.udg=r.udg.data(); r.sol.uh=r.uh.data();
            compute_nonmatching_coupling<Model>(*runtime,r.sol,residual,r.app,r.master,r.mesh,tmp,
                common,0,false,0);
            return std::vector<dstype>(rd.flux.data,rd.flux.data+rd.flux.size);
        };
        plus=perturb(1.0); minus=perturb(-1.0);
        r.udg=baseUdg; r.uh=baseUh; r.sol.udg=r.udg.data(); r.sol.uh=r.uh.data();
        compute_nonmatching_coupling<Model>(*runtime,r.sol,residual,r.app,r.master,r.mesh,tmp,
            common,0,true,0);
        for(Int q=0;q<rd.view.npts;++q) for(Int out=0;out<ncu12;++out) {
            dstype tangent=0;
            for(Int c=0;c<nc;++c) tangent+=rd.fluxUdg.data[q+rd.view.npts*(out+ncu12*c)]*du[c];
            for(Int c=0;c<ncu;++c) {
                dstype corrected=duh[c];
                if(ncq>0) for(Int d=0;d<3;++d)
                    corrected-=rd.view.pd[q+rd.view.npts*d]*du[ncu+c+ncu*d];
                tangent+=rd.fluxUhg.data[q+rd.view.npts*(out+ncu12*c)]*corrected;
            }
            const dstype fd=(plus[q+rd.view.npts*out]-minus[q+rd.view.npts*out])/(2*eps);
            fdError=std::max(fdError,std::abs(fd-tangent)/std::max<dstype>(1.0,std::abs(tangent)));
        }
    }

    std::vector<dstype> expectedRi(donor.szRi,0.0),expectedHi(donor.szHi,0.0);
    for(Int q=0;q<donor.npts;++q) {
        const Int slot=donor.pslot[q];
        for(Int i=0;i<m.npf;++i) {
            const dstype W=donor.pwJ[q]*m.shapfgt[donor.pg[q]+m.ngf*i];
            for(Int out=0;out<ncu12;++out)
                expectedRi[out+ncu12*(i+m.npf*slot)]-=W*rd.flux.data[q+donor.npts*out];
        }
    }
    for(Int pair=0;pair<donor.npairs;++pair) {
        const Int e=donor.pairelem[pair],slot=donor.pairslot[pair];
        std::vector<dstype> K(static_cast<std::size_t>(m12)*n,0.0),H(static_cast<std::size_t>(m12)*mtrace,0.0);
        for(Int qi=donor.pairptr[pair];qi<donor.pairptr[pair+1];++qi) {
            const Int q=qi,a=donor.pa[q];
            for(Int i=0;i<m.npf;++i) {
                const dstype W=donor.pwJ[q]*m.shapfgt[donor.pg[q]+m.ngf*i];
                for(Int out=0;out<ncu12;++out) for(Int c=0;c<ncu;++c) {
                    const dstype fu=rd.fluxUdg.data[q+donor.npts*(out+ncu12*c)];
                    const dstype fuh=rd.fluxUhg.data[q+donor.npts*(out+ncu12*c)];
                    for(Int j=0;j<m.npe;++j) {
                        dstype derivative=fu*donor.pphi[j+m.npe*q];
                        if(ncq==0) for(Int d=0;d<3;++d)
                            derivative+=fuh*donor.pd[q+donor.npts*d]*
                                donor.pdphibar[j+m.npe*(d+3*q)];
                        K[(out+ncu12*i)+m12*(j+m.npe*c)]+=W*derivative;
                    }
                    for(Int j=0;j<m.npf;++j)
                        H[(out+ncu12*i)+m12*(c+ncu*(j+m.npf*a))]+=
                            W*fuh*donor.ppsi[j+m.npf*q];
                }
            }
        }
        if(ncq>0) for(Int d=0;d<3;++d) {
            std::vector<dstype> G(static_cast<std::size_t>(m12)*m.npe*ncu,0.0);
            for(Int qi=donor.pairptr[pair];qi<donor.pairptr[pair+1];++qi) {
                const Int q=qi;
                for(Int i=0;i<m.npf;++i) {
                    const dstype W=donor.pwJ[q]*m.shapfgt[donor.pg[q]+m.ngf*i];
                    for(Int out=0;out<ncu12;++out) for(Int c=0;c<ncu;++c) {
                        const Int qc=ncu+c+ncu*d;
                        const dstype fq=rd.fluxUdg.data[q+donor.npts*(out+ncu12*qc)];
                        const dstype fuh=rd.fluxUhg.data[q+donor.npts*(out+ncu12*c)];
                        for(Int j=0;j<m.npe;++j)
                            G[(out+ncu12*i)+m12*(j+m.npe*c)]+=W*(fq*donor.pphi[j+m.npe*q]-
                                fuh*donor.pd[q+donor.npts*d]*donor.pphibar[j+m.npe*q]);
                    }
                }
            }
            for(Int row=0;row<m12;++row) for(Int c=0;c<ncu;++c) {
                for(Int j=0;j<m.npe;++j) for(Int k=0;k<m.npe;++k)
                    K[row+m12*(j+m.npe*c)]+=G[row+m12*(k+m.npe*c)]*
                        C[k+m.npe*j+static_cast<std::size_t>(m.npe)*m.npe*(e+ne*d)];
                for(Int j=0;j<ndf;++j) for(Int k=0;k<m.npe;++k)
                    H[row+m12*(c+ncu*j)]-=G[row+m12*(k+m.npe*c)]*
                        E[k+m.npe*j+static_cast<std::size_t>(m.npe)*ndf*(e+ne*d)];
            }
        }
        for(Int row=0;row<m12;++row) {
            for(Int col=0;col<mtrace;++col) {
                dstype value=H[row+m12*col];
                for(Int j=0;j<n;++j) value+=K[row+m12*j]*F[j+n*(col+static_cast<std::size_t>(mtrace)*e)];
                expectedHi[row+m12*(col+static_cast<std::size_t>(mtrace)*pair)]=value;
            }
            dstype value=0;
            for(Int j=0;j<n;++j) value-=K[row+m12*j]*Ru[j+n*e];
            expectedRi[row+m12*slot]+=value;
        }
    }
    dstype residualError=0,matrixError=0;
    for(Int i=0;i<donor.szRi;++i) residualError=std::max(residualError,std::abs(rd.Ri.data[i]-expectedRi[i]));
    for(Int i=0;i<donor.szHi;++i) matrixError=std::max(matrixError,std::abs(rd.Hi.data[i]-expectedHi[i]));
    const dstype matvecError=verify_runtime_matvec(name,r,m,common,residual,nm,*runtime,ncu,ncu12,worldRank);
    if(fluxError>5e-13 || jacError>5e-13 || residualError>5e-13 || matrixError>5e-13 ||
            wError>5e-13 || wJacError>5e-13 || fdError>=1e-6 || matvecError>=1e-13) {
        std::printf("FAIL 3D model operators %s family %d rank %d flux %.3e jac %.3e Ri %.3e Hi %.3e w %.3e wjac %.3e fd %.3e mv %.3e\n",
            name,elemtype,worldRank,fluxError,jacError,residualError,matrixError,wError,wJacError,
            fdError,matvecError); ++failures;
    }
    if(worldRank==0)
        std::printf("3D model operators %s family %d: flux %.3e jac %.3e Ri %.3e Hi %.3e w %.3e wjac %.3e fd %.3e matvec %.3e\n",
            name,elemtype,fluxError,jacError,residualError,matrixError,wError,wJacError,fdError,
            matvecError);
    free_nonmatching_data(nm); runtime.reset();
    CPUFREE(common.requests); CPUFREE(common.statuses);
}

void orientation_runtime_case(int elemtype,int p,int worldRank,int worldSize)
{
    using namespace exasim::nonmatching;
    const Int split=worldSize/2,model=worldRank<split?0:1,part=model==0?worldRank:worldRank-split;
    SetupMaster3D m=setup_master(elemtype,p); SetupRank3D r;
    setup_multi_rank_3d(r,m,model,part,split,0.0,1,0,0,1);
    const Int ne=2,ndf=m.npf*m.nfe,mtrace=ndf,m12=m.npf;
    r.udg.assign(static_cast<std::size_t>(m.npe)*ne,0.0);
    r.uh.resize(static_cast<std::size_t>(ndf)*ne);
    for(std::size_t i=0;i<r.uh.size();++i) r.uh[i]=0.11+0.002*(i%37);
    r.sol.udg=r.udg.data(); r.sol.uh=r.uh.data();
    std::vector<dstype> tau(1,1.0),param(1,1.0),uinf(1,0.0);
    r.app.tau=tau.data(); r.app.physicsparam=param.data(); r.app.uinf=uinf.data();
    commonstruct common{}; common.components.nc=1; common.components.ncu=1;
    common.components.ncq=0; common.components.ncx=3; common.grid.nd=3;
    common.grid.npe=m.npe; common.grid.npf=m.npf; common.grid.ngf=m.ngf;
    common.meshsizes.ne=ne; common.meshsizes.ne0=ne; common.meshsizes.ne1=ne;
    common.meshsizes.nfe=m.nfe; common.spatialScheme=1; common.szinterfacefluxmap=1;
    common.couplingparams.coupledboundarycondition=2;
    common.couplingparams.coupledcondition=1; common.couplingparams.coupledinterface=1;
    common.couplingparams.interfacetype=1;
    nonmatchingdata nm; std::unique_ptr<NonmatchingRuntime<dstype,Int>> runtime;
    rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,common,worldSize,worldRank,model,
        nm,runtime,0,static_cast<DonorSearchResult<dstype,Int>*>(nullptr));
    std::vector<dstype> F(static_cast<std::size_t>(m.npe)*mtrace*ne,0.0),Ru(static_cast<std::size_t>(m.npe)*ne,0.0);
    resstruct residual{}; residual.F=F.data(); residual.Ru=Ru.data(); tempstruct tmp{};
    const int norient=elemtype==0?6:8;
    dstype worstResidual=0,worstMatrix=0,worstMatvec=0;
    SurfaceNodalBasis basis(m.xpf.data(),m.npf,p,elemtype);
    for(int orientation=0;orientation<norient;++orientation) {
        refresh_nonmatching_runtime(*runtime,nm,r.app,r.mesh,common,Int(0));
        auto& rd=runtime->dir[1-model]; const nonmatchinginterface& donor=nm.dir[1-model];
        std::vector<dstype> psi(m.npf),dpsi(static_cast<std::size_t>(2)*m.npf);
        for(Int q=0;q<donor.npts;++q) {
            const dstype in[2]={donor.pxi[q],donor.pxi[q+donor.npts]};
            dstype out[2]; transform_face_point(elemtype,orientation,in,out);
            basis.evaluate(psi.data(),dpsi.data(),out);
            for(Int j=0;j<m.npf;++j) rd.ppsi.data[j+m.npf*q]=psi[j];
        }
        compute_nonmatching_coupling<OrientationCoupled3D>(*runtime,r.sol,residual,r.app,
            r.master,r.mesh,tmp,common,0,true,0);
        std::vector<dstype> expectedRi(donor.szRi,0.0),expectedHi(donor.szHi,0.0);
        for(Int q=0;q<donor.npts;++q) {
            dstype uh=0;
            const Int e=donor.pe[q],a=donor.pa[q];
            for(Int j=0;j<m.npf;++j) {
                const Int encoded=r.elemcon[j+m.npf*a+ndf*e];
                uh+=rd.ppsi.data[j+m.npf*q]*r.uh[encoded];
            }
            const Int slot=donor.pslot[q];
            for(Int i=0;i<m.npf;++i) {
                const dstype W=donor.pwJ[q]*m.shapfgt[donor.pg[q]+m.ngf*i];
                expectedRi[i+m.npf*slot]-=W*uh;
            }
        }
        for(Int pair=0;pair<donor.npairs;++pair) {
            const Int a=donor.pa[donor.pairptr[pair]];
            for(Int q=donor.pairptr[pair];q<donor.pairptr[pair+1];++q)
                for(Int i=0;i<m.npf;++i) for(Int j=0;j<m.npf;++j) {
                    const dstype W=donor.pwJ[q]*m.shapfgt[donor.pg[q]+m.ngf*i];
                    const Int col=j+m.npf*a;
                    expectedHi[i+m12*(col+static_cast<std::size_t>(mtrace)*pair)]+=
                        W*rd.ppsi.data[j+m.npf*q];
                }
        }
        for(Int i=0;i<donor.szRi;++i)
            worstResidual=std::max(worstResidual,std::abs(rd.Ri.data[i]-expectedRi[i]));
        for(Int i=0;i<donor.szHi;++i)
            worstMatrix=std::max(worstMatrix,std::abs(rd.Hi.data[i]-expectedHi[i]));
        worstMatvec=std::max(worstMatvec,verify_runtime_matvec("orientation",r,m,common,
            residual,nm,*runtime,1,1,worldRank));
    }
    dstype global[3]={0,0,0},local[3]={worstResidual,worstMatrix,worstMatvec};
    MPI_Allreduce(local,global,3,MPI_DOUBLE,MPI_MAX,MPI_COMM_WORLD);
    if(global[0]>5e-13 || global[1]>5e-13 || global[2]>=1e-13) {
        std::printf("FAIL 3D runtime orientations family %d rank %d residual %.3e Hi %.3e matvec %.3e\n",
            elemtype,worldRank,global[0],global[1],global[2]); ++failures;
    }
    if(worldRank==0) std::printf("3D runtime orientations family %d count %d: residual %.3e Hi %.3e matvec %.3e\n",
        elemtype,norient,global[0],global[1],global[2]);
    free_nonmatching_data(nm); runtime.reset(); CPUFREE(common.requests); CPUFREE(common.statuses);
}

std::vector<Int> face_orientation_permutation(const SetupMaster3D& m,int orientation)
{
    std::vector<Int> permutation(m.npf,-1);
    for(Int i=0;i<m.npf;++i) {
        const dstype in[2]={m.xpf[i],m.xpf[i+m.npf]}; dstype out[2];
        transform_face_point(m.elemtype,orientation,in,out);
        for(Int j=0;j<m.npf;++j)
            if(std::abs(out[0]-m.xpf[j])<1e-12 && std::abs(out[1]-m.xpf[j+m.npf])<1e-12)
                permutation[i]=j;
        if(permutation[i]<0) { std::printf("FAIL orientation node permutation\n"); ++failures; }
    }
    return permutation;
}

void matching_matvec_case(int elemtype,int p,int worldRank,int worldSize)
{
    using namespace exasim::nonmatching;
    const Int split=worldSize/2,model=worldRank<split?0:1,part=model==0?worldRank:worldRank-split;
    const Int ne=2,ncu=1,ncu12=1;
    SetupMaster3D m=setup_master(elemtype,p); SetupRank3D r;
    setup_multi_rank_3d(r,m,model,part,split,0.0,ncu,0,0,ncu12);
    // Undo the half-face stagger used by the multi-donor fixture.
    for(Int e=0;e<ne;++e) for(Int j=0;j<m.npe;++j)
        r.xdg[j+m.npe+static_cast<std::size_t>(3)*m.npe*e]+=
            4.0*part+e+(model==1?0.5:0.0);
    const Int ndf=m.npf*m.nfe,mtrace=ndf,m12=m.npf,nf=m.nfe*ne,N=m.npf*nf;
    r.udg.assign(static_cast<std::size_t>(m.npe)*ne,0.0); r.uh.resize(static_cast<std::size_t>(ndf)*ne);
    for(std::size_t i=0;i<r.uh.size();++i) r.uh[i]=0.15+0.001*(i%53);
    r.sol.udg=r.udg.data(); r.sol.uh=r.uh.data();
    std::vector<dstype> tau(1,1.0),param(1,1.0),uinf(1,0.0);
    r.app.tau=tau.data(); r.app.physicsparam=param.data(); r.app.uinf=uinf.data();
    commonstruct common{}; common.components.nc=1; common.components.ncu=1;
    common.components.ncx=3; common.grid.nd=3; common.grid.npe=m.npe;
    common.grid.npf=m.npf; common.grid.ngf=m.ngf; common.meshsizes.ne=ne;
    common.meshsizes.ne0=ne; common.meshsizes.ne1=ne; common.meshsizes.nfe=m.nfe;
    common.meshsizes.nf=nf; common.meshsizes.nf0=nf; common.spatialScheme=1;
    common.szinterfacefluxmap=1; common.couplingparams.coupledboundarycondition=2;
    common.couplingparams.coupledcondition=1; common.couplingparams.coupledinterface=1;
    common.couplingparams.interfacetype=1;
    nonmatchingdata nm; std::unique_ptr<NonmatchingRuntime<dstype,Int>> runtime;
    rebuild_nonmatching_interface(r.app,r.master,r.mesh,r.sol,common,worldSize,worldRank,model,
        nm,runtime,0,static_cast<DonorSearchResult<dstype,Int>*>(nullptr));
    std::vector<dstype> F(static_cast<std::size_t>(m.npe)*mtrace*ne,0.0),Ru(static_cast<std::size_t>(m.npe)*ne,0.0);
    resstruct residual{}; residual.F=F.data(); residual.Ru=Ru.data(); tempstruct couplingTmp{};
    compute_nonmatching_coupling<OrientationCoupled3D>(*runtime,r.sol,residual,r.app,r.master,
        r.mesh,couplingTmp,common,0,true,0);

    r.f2e.assign(static_cast<std::size_t>(4)*nf,-1);
    for(Int e=0;e<ne;++e) for(Int lf=0;lf<m.nfe;++lf) {
        const Int face=lf+m.nfe*e; r.f2e[4*face]=e; r.f2e[4*face+1]=lf;
    }
    r.mesh.f2e=r.f2e.data();
    std::vector<dstype> v(N),AE(static_cast<std::size_t>(mtrace)*mtrace*ne,0.0),
        ve(static_cast<std::size_t>(mtrace)*ne),we(ve.size()),wn(N),wc(N);
    for(Int i=0;i<N;++i) v[i]=0.03+0.0009*((i+11*worldRank)%71);
    std::vector<dstype> dummy(1,0.0),faceSend(static_cast<std::size_t>(m12)*ne),
        faceRecv(static_cast<std::size_t>(m12)*ne);
    tempstruct tmp{}; tmp.buffsend=dummy.data(); tmp.buffrecv=dummy.data();
    tmp.bufffacesend=faceSend.data(); tmp.bufffacerecv=faceRecv.data();
    common.nnbsd=0; common.nelemsend=0; common.nelemrecv=0;
    common.meshsizes.ne0=0;
    hdgMatVec<dstype,Int>(wn.data(),AE.data(),v.data(),ve.data(),we.data(),residual,
        r.app,r.mesh,common,tmp,0,0,runtime.get());

    const nonmatchinginterface& donor=nm.dir[1-model];
    const nonmatchinginterface& owner=nm.dir[model];
    std::vector<dstype> confHi(static_cast<std::size_t>(m12)*mtrace*ne,0.0),confRi(static_cast<std::size_t>(m12)*ne,0.0);
    std::vector<Int> faceperm;
    if(elemtype==0) {
        faceperm.resize(static_cast<std::size_t>(m.npf)*ne);
        for(Int e=0;e<ne;++e) {
            const auto perm=face_orientation_permutation(m,e==0?0:3);
            std::copy(perm.begin(),perm.end(),faceperm.begin()+static_cast<std::size_t>(m.npf)*e);
        }
    }
    else faceperm=face_orientation_permutation(m,4);
    dstype blockError=0;
    for(Int pair=0;pair<donor.npairs;++pair) {
        const Int e=donor.pairelem[pair],slot=donor.pairslot[pair];
        const Int targetFace=static_cast<Int>(donor.slotface[slot]%m.nfe==0 ?
            (donor.slotface[slot]/m.nfe)%ne : e);
        const Int faceIndex=std::max<Int>(0,std::min<Int>(ne-1,targetFace));
        for(Int n=0;n<m.npf;++n) {
            const Int pn=faceperm[n+(elemtype==0?m.npf*faceIndex:0)];
            for(Int col=0;col<mtrace;++col) {
                const dstype value=runtime->dir[1-model].Hi.data[n+m12*(col+static_cast<std::size_t>(mtrace)*pair)];
                confHi[pn+m12*(col+static_cast<std::size_t>(mtrace)*e)]=value;
                blockError=std::max(blockError,std::abs(confHi[pn+m12*(col+static_cast<std::size_t>(mtrace)*e)]-value));
            }
        }
    }
    std::vector<Int> nbintf(1),sendpts(1,ne),recvpts(1,ne),facesend(ne),facerecv(ne);
    nbintf[0]=model==0?part+split:part;
    for(Int e=0;e<ne;++e) { facesend[e]=e; facerecv[e]=e; }
    common.couplingparams.interfacetype=0; common.couplingparams.nintfaces=ne;
    common.nnbintf=1; common.nfacesend=ne; common.nfacerecv=ne;
    common.nbintf=nbintf.data(); common.facesendpts=sendpts.data(); common.facerecvpts=recvpts.data();
    r.mesh.facesend=facesend.data(); r.mesh.facerecv=facerecv.data();
    r.mesh.faceperm=faceperm.data(); r.mesh.szfaceperm=static_cast<Int>(faceperm.size());
    residual.Hi=confHi.data(); residual.Ri=confRi.data();
    std::fill(ve.begin(),ve.end(),0.0); std::fill(we.begin(),we.end(),0.0);
    hdgMatVec<dstype,Int>(wc.data(),AE.data(),v.data(),ve.data(),we.data(),residual,
        r.app,r.mesh,common,tmp,0,0,nullptr);
    dstype local=0,scale=0;
    for(Int i=0;i<N;++i) { local=std::max(local,std::abs(wc[i]-wn[i])); scale=std::max(scale,std::abs(wn[i])); }
    dstype global=0,globalScale=0; MPI_Allreduce(&local,&global,1,MPI_DOUBLE,MPI_MAX,MPI_COMM_WORLD);
    MPI_Allreduce(&scale,&globalScale,1,MPI_DOUBLE,MPI_MAX,MPI_COMM_WORLD);
    const dstype error=global/std::max<dstype>(1.0,globalScale);
    if(error>=1e-13 || blockError>5e-13 || (elemtype==0 && r.mesh.szfaceperm!=m.npf*ne) ||
            (elemtype==1 && r.mesh.szfaceperm!=m.npf)) {
        std::printf("FAIL 3D matching type0/type1 family %d rank %d block %.3e matvec %.3e faceperm %d\n",
            elemtype,worldRank,blockError,error,int(r.mesh.szfaceperm)); ++failures;
    }
    if(worldRank==0) std::printf("3D matching type0/type1 family %d: faceperm %s block %.3e matvec %.3e\n",
        elemtype,elemtype==0?"expanded":"compact",blockError,error);
    (void)owner;
    free_nonmatching_data(nm); runtime.reset(); CPUFREE(common.requests); CPUFREE(common.statuses);
}

struct SearchMaster {
    Int npf = 0;
    std::vector<dstype> xpf;
};

SearchMaster search_master(int elemtype, int p)
{
    SearchMaster out;
    std::vector<dstype> xpe;
    std::vector<int> telem,tface,perm;
    masternodes(xpe,telem,out.xpf,tface,perm,p,3,elemtype,data_path("masternodes.bin"));
    out.npf=static_cast<Int>(out.xpf.size()/2);
    return out;
}

void search_case(int elemtype, int p, int worldRank, int worldSize, bool localized,
                 int modelSplit = -1)
{
    using namespace exasim::nonmatching;
    namespace pp = exasim::nonmatching::preprocess;
    const int split = modelSplit > 0 ? modelSplit : worldSize/2;
    const int model = worldRank < split ? 0 : 1;
    const int part = model == 0 ? worldRank : worldRank-split;
    const int modelRanks = model == 0 ? split : worldSize-split;
    const SearchMaster m = search_master(elemtype,p);
    InterfaceFaceSet<dstype,Int> own;
    own.nd = 3; own.npf = m.npf;
    own.rank.push_back(worldRank); own.model.push_back(model);
    own.elem.push_back(0); own.lface.push_back(0);
    // Reverse the rank/global ordering to test that D5 uses global face IDs,
    // not D3's world-rank tie break.
    own.global.push_back(model*10000 + (modelRanks-part));
    own.nodes.resize(static_cast<std::size_t>(3)*m.npf);
    const dstype shift = localized ? static_cast<dstype>(3*part) : 0.0;
    for (Int a=0;a<m.npf;++a) {
        const dstype u=m.xpf[a], v=m.xpf[a+m.npf];
        own.nodes[a] = shift+u;
        own.nodes[a+m.npf] = v;
        own.nodes[a+2*m.npf] = 0.07*u*(1-u)+0.05*v*(1-v)+0.03*u*v;
    }
    const auto prepared=pp::prepare_faces<dstype,Int>(own,m.xpf.data(),elemtype,p);
    const dstype ref[5][2]={{0.19,0.17},{0.47,0.11},{0.08,0.51},{0.0,0.35},{0.31,0.0}};
    std::vector<dstype> ownerPoints(15,0);
    pp::ProjectionWorkspace<dstype,Int> mapWork;
    for(int q=0;q<5;++q) {
        dstype z[2]={ref[q][0],ref[q][1]};
        if(elemtype==0 && z[0]+z[1]>1) z[1]=1-z[0];
        const dstype target[3]={0,0,0};
        (void)pp::map_face(prepared.master,prepared.control.data(),target,z,mapWork);
        for(int d=0;d<3;++d) ownerPoints[d+3*q]=static_cast<dstype>(mapWork.physical[d]);
        ownerPoints[2+3*q]+=0.025;
    }
    auto communicator=pp::make_interface_communicator<Int>(true,worldRank,model);
    pp::DistributedStatistics statistics;
    const double searchBegin=MPI_Wtime();
    const auto donors=pp::distributed_search(communicator,prepared,ownerPoints,
        static_cast<Int>(worldRank),static_cast<Int>(model),dstype(1e-13),Int(100),&statistics);
    const double searchSeconds=MPI_Wtime()-searchBegin;

    for(Int q=0;q<static_cast<Int>(donors.size());++q) {
        if(!donors[q].converged) {
            std::printf("FAIL 3D search unconverged family %d p %d rank %d point %d\n",
                elemtype,p,worldRank,int(q));
            ++failures;
        }
        if(!localized) {
            const Int expected=(1-model)*10000+1;
            if(donors[q].face!=expected) {
                std::printf("FAIL 3D global-index tie family %d p %d rank %d got %d expected %d\n",
                    elemtype,p,worldRank,int(donors[q].face),int(expected));
                ++failures;
            }
        }
    }
    for(int s=0;s<=20;++s)
        for(int t=0;t<=20;++t) {
            if(elemtype==0 && s+t>20) continue;
            const dstype xi[2]={dstype(s)/20,dstype(t)/20};
            const dstype target[3]={0,0,0};
            (void)pp::map_face(prepared.master,prepared.control.data(),target,xi,mapWork);
            for(int d=0;d<3;++d)
                if(mapWork.physical[d]<prepared.boxMin[d] ||
                   mapWork.physical[d]>prepared.boxMax[d]) {
                    std::printf("FAIL 3D processor box enclosure family %d rank %d\n",elemtype,worldRank);
                    ++failures;
                }
        }
    long long evaluated=0, fullFaceCount=0, maxEvaluated=0;
    MPI_Allreduce(&statistics.facesEvaluated,&evaluated,1,MPI_LONG_LONG,MPI_SUM,communicator.comm);
    MPI_Allreduce(&statistics.facesEvaluated,&maxEvaluated,1,MPI_LONG_LONG,MPI_MAX,communicator.comm);
    const long long localFullFaceCount=static_cast<long long>(donors.size())*
        (model==0?worldSize-split:split);
    MPI_Allreduce(&localFullFaceCount,&fullFaceCount,1,MPI_LONG_LONG,MPI_SUM,communicator.comm);
    if(localized && worldSize==8 && !(evaluated*2<fullFaceCount)) {
        std::printf("FAIL 3D localized pruning evaluated %lld full-face work %lld\n",
            evaluated,fullFaceCount);
        ++failures;
    }
    if(worldRank==0)
        std::printf("3D search family %d p %d localized %d split %d+%d: evaluated %lld full-face work %lld max/rank %lld\n",
            elemtype,p,localized?1:0,split,worldSize-split,evaluated,fullFaceCount,maxEvaluated);
    if(runCost) {
        long long sums[8]={communicator.size,statistics.ownerPoints,
            statistics.d4Queries,statistics.facesEvaluated,statistics.boxBytes,
            statistics.countBytes,statistics.queryBytes,statistics.responseBytes};
        long long totals[8]={0};
        double searchMaximum=0;
        MPI_Reduce(sums,totals,8,MPI_LONG_LONG,MPI_SUM,0,communicator.comm);
        MPI_Reduce(&searchSeconds,&searchMaximum,1,MPI_DOUBLE,MPI_MAX,0,communicator.comm);
        if(communicator.rank==0) {
            const double pointScale=std::max<long long>(1,totals[1]);
            std::printf("3D SEARCH COST family %d ranks/model %d boxes %.0f candidates/point %.6f queried/point %.6f search %.6e search/point %.6e bytes %lld\n",
                elemtype,split,double(totals[0])/std::max(1,communicator.size),double(totals[3])/pointScale,
                1.0+double(totals[2])/pointScale,searchMaximum,searchMaximum/pointScale,
                totals[4]+totals[5]+totals[6]+totals[7]);
        }
    }
}
#endif

