// Curved p=4 multi-start projection benchmark (serial, informational).
void curved_cost_case()
{
    using namespace exasim::nonmatching;
    namespace pp = exasim::nonmatching::preprocess;
    for (int elemtype : {0, 1}) {
        const int p = 4;
        std::vector<dstype> xpe, xpf;
        std::vector<int> telem, tface, perm;
        masternodes(xpe, telem, xpf, tface, perm, p, 3, elemtype, data_path("masternodes.bin"));
        const Int npf = static_cast<Int>(xpf.size() / 2);
        for (dstype amplitude : {0.0, 0.05, 0.2}) {
            InterfaceFaceSet<dstype,Int> face;
            face.nd=3;face.npf=npf;face.rank={0};face.model={0};face.elem={0};
            face.lface={0};face.global={0};face.nodes.resize(static_cast<std::size_t>(npf)*3);
            for (Int a = 0; a < npf; ++a) {
                const dstype s = xpf[a], t = xpf[a + npf];
                face.nodes[a]=s;face.nodes[a+npf]=t;
                face.nodes[a+2*npf]=amplitude*std::sin(M_PI*s)*std::sin(M_PI*t);
            }
            const auto prepared=pp::prepare_faces<dstype,Int>(face,xpf.data(),elemtype,p);
            for (dstype delta : {0.0, 0.01, 0.1}) {
                long long failed = 0, points = 0;
                pp::ProjectionWorkspace<dstype,Int> work;
                const auto start = std::chrono::steady_clock::now();
                const int n = 20;
                for (int i = 0; i <= n; ++i)
                    for (int j = 0; j <= n; ++j) {
                        const dstype s = static_cast<dstype>(i) / n, t = static_cast<dstype>(j) / n;
                        if (elemtype == 0 && s + t > 1) continue;
                        const dstype xi[2]={s,t},zero[3]={0,0,0};
                        (void)pp::map_face(prepared.master,prepared.control.data(),zero,xi,work);
                        dstype x[3]={static_cast<dstype>(work.physical[0]),
                            static_cast<dstype>(work.physical[1]),
                            static_cast<dstype>(work.physical[2])+delta};
                        const auto result=pp::project_face_multistart(
                            prepared,0,x,dstype(1e-13),Int(100),work);
                        if (!result.converged) ++failed;
                        ++points;
                    }
                const double seconds = std::chrono::duration<double>(
                    std::chrono::steady_clock::now() - start).count();
                std::printf("MULTISTART CURVED COST %s p=4 A=%.2f delta=%.2f points %lld "
                    "starts %lld iterations %lld failed %lld time/call %.3e s\n",
                    elemtype == 0 ? "tri" : "quad", amplitude, delta, points,
                    work.projectionStarts,work.projectionIterations,failed,seconds/points);
            }
        }
    }
}

int main(int argc, char** argv)
{
    for (int i = 1; i < argc; ++i)
        if (std::strcmp(argv[i], "--report-only") == 0) strict = false;
        else if (std::strcmp(argv[i], "--search") == 0) runSearch = true;
        else if (std::strcmp(argv[i], "--setup") == 0) runSetup = true;
        else if (std::strcmp(argv[i], "--operators") == 0) runOperators = true;
        else if (std::strcmp(argv[i], "--rebuild") == 0) runRebuild = true;
        else if (std::strcmp(argv[i], "--multi") == 0) runMulti = true;
        else if (std::strcmp(argv[i], "--orientations") == 0) runOrientations = true;
        else if (std::strcmp(argv[i], "--cost") == 0) runCost = true;
        else if (std::strcmp(argv[i], "--reject-tet-hex") == 0) rejectMode = RejectMode::TetHex;
        else if (std::strcmp(argv[i], "--reject-porder") == 0) rejectMode = RejectMode::Porder;
        else if (std::strcmp(argv[i], "--reject-quadrature") == 0) rejectMode = RejectMode::Quadrature;
        else if (std::strcmp(argv[i], "--reject-patch") == 0) rejectMode = RejectMode::Patch;
        else if (std::strcmp(argv[i], "--reject-rank-config") == 0) rejectMode = RejectMode::RankConfig;
        else if (std::strcmp(argv[i], "--curved-cost") == 0) runCurvedCost = true;
        else if (std::strcmp(argv[i], "--reject-volume-basis") == 0) rejectMode = RejectMode::VolumeBasis;
        else if (std::strcmp(argv[i], "--reject-singular-map") == 0) rejectMode = RejectMode::SingularMap;
        else if (std::strcmp(argv[i], "--reject-projection") == 0) rejectMode = RejectMode::Projection;
#ifdef HAVE_MPI
    MPI_Init(&argc, &argv);
    EXASIM_COMM_WORLD = MPI_COMM_WORLD;
    int worldRank=0, worldSize=1;
    MPI_Comm_rank(MPI_COMM_WORLD,&worldRank);
    MPI_Comm_size(MPI_COMM_WORLD,&worldSize);
#endif
    Kokkos::initialize(argc,argv);
    Diff tetMaster, tetTypeOne, hexMaster;
    for (int p = 1; p <= 4; ++p) {
        const StageReport r = family_case(0, p);
        tetMaster.merge(r.basisMaster);
        tetTypeOne.merge(r.basisTypeOne);
    }
    for (int p = 1; p <= 3; ++p) hexMaster.merge(family_case(1, p).basisMaster);
#ifdef HAVE_MPI
    if(runSearch || runCost) {
        if(worldSize!=2 && worldSize!=4 && worldSize!=8) {
            if(worldRank==0) std::printf("FAIL --search requires 2, 4 or 8 ranks\n");
            ++failures;
        }
        else {
            if(runSearch) {
                search_case(0,2,worldRank,worldSize,false);
                search_case(1,4,worldRank,worldSize,false);
            }
            search_case(0,4,worldRank,worldSize,true);
            search_case(1,4,worldRank,worldSize,true);
            if(worldSize==4) {
                search_case(0,4,worldRank,worldSize,false,1);
                search_case(1,4,worldRank,worldSize,false,1);
            }
            if(worldSize==8) {
                search_case(0,4,worldRank,worldSize,false,3);
                search_case(1,4,worldRank,worldSize,false,3);
            }
            if(runCost) {
                cost_runtime_case(0,worldRank,worldSize);
                cost_runtime_case(1,worldRank,worldSize);
            }
        }
    }
    if(runCurvedCost && worldRank==0) curved_cost_case();
    if(rejectMode!=RejectMode::None) {
        if(worldSize!=2 && worldSize!=4 && worldSize!=8) {
            if(worldRank==0) std::printf("FAIL expected-failure modes require 2, 4 or 8 ranks\n");
            ++failures;
        }
        else reject_setup_case(rejectMode,worldRank,worldSize);
    }
    if(runSetup || runOperators || runRebuild) {
        if(worldSize!=2 && worldSize!=4 && worldSize!=8) {
            if(worldRank==0) std::printf("FAIL --setup requires 2, 4 or 8 ranks\n");
            ++failures;
        }
        else {
            setup_case(0,2,worldRank,worldSize);
            setup_case(1,2,worldRank,worldSize);
            if(runRebuild) {
                setup_case(0,2,worldRank,worldSize,0.02);
                setup_case(1,2,worldRank,worldSize,0.02);
            }
        }
    }
    if(runMulti || runRebuild) {
        if(worldSize!=2 && worldSize!=4 && worldSize!=8) {
            if(worldRank==0) std::printf("FAIL --multi requires 2, 4 or 8 ranks\n");
            ++failures;
        }
        else {
            multi_setup_case(0,2,worldRank,worldSize);
            multi_setup_case(1,2,worldRank,worldSize);
        }
    }
    if(runOperators) {
        if(worldSize!=2 && worldSize!=4 && worldSize!=8) {
            if(worldRank==0) std::printf("FAIL --operators requires 2, 4 or 8 ranks\n");
            ++failures;
        }
        else {
            model_operator_case<NLCoupled3D>("q-present",0,2,worldRank,worldSize);
            model_operator_case<NLCoupled3D>("q-present",1,2,worldRank,worldSize);
            model_operator_case<QFreeCoupled3D>("q-free",0,2,worldRank,worldSize,0.015);
            model_operator_case<QFreeCoupled3D>("q-free",1,2,worldRank,worldSize,0.015);
            model_operator_case<WCoupled3D>("ncw=2",0,2,worldRank,worldSize,0.01);
            model_operator_case<WCoupled3D>("ncw=2",1,2,worldRank,worldSize,0.01);
            matching_matvec_case(0,2,worldRank,worldSize);
            matching_matvec_case(1,2,worldRank,worldSize);
        }
    }
    if(runOrientations) {
        orientation_operator_case(0,3,worldRank);
        orientation_operator_case(1,3,worldRank);
        orientation_runtime_case(0,3,worldRank,worldSize);
        orientation_runtime_case(1,3,worldRank,worldSize);
    }
#endif
    std::printf("summary: tet master face table max abs %.3e, tet type-1 basis max abs %.3e, "
                "hex master face table max abs %.3e\n", tetMaster.abs, tetTypeOne.abs, hexMaster.abs);
#ifdef HAVE_MPI
    int globalFailures=0;
    MPI_Allreduce(&failures,&globalFailures,1,MPI_INT,MPI_MAX,MPI_COMM_WORLD);
    failures=globalFailures;
#endif
    Kokkos::finalize();
#ifdef HAVE_MPI
    MPI_Finalize();
#endif
    if (failures == 0) std::printf("PASS nonmatching_3d%s\n", strict ? "" : " (report only)");
    else std::printf("FAIL nonmatching_3d: %d check(s)\n", failures);
    return failures == 0 ? 0 : 1;
}
